def _canonical_static_denominator_rule() -> str:
    return (
        "legacy_static_current_canonical_gdp_share_not_empirical_runtime_anchor;"
        f"center_pp_gdp={LITERATURE_ANNUAL_FLOW_RUNTIME_ANCHOR_PP_STR}"
    )


def _canonical_static_denominator_phrase() -> str:
    return (
        f"static current-canonical {LITERATURE_ANNUAL_FLOW_RUNTIME_ANCHOR_PP_STR} "
        "pp GDP denominator lane"
    )


def _decimal_or_zero(value: str) -> Decimal:
    try:
        return Decimal(value or "0")
    except Exception:
        return Decimal("0")


def _decimal_or_none(value: object) -> Decimal | None:
    if value in (None, "", "."):
        return None
    try:
        return Decimal(str(value).replace(",", ""))
    except Exception:
        return None


def _format_decimal(value: Decimal) -> str:
    return str(value)


def _row_source_status(
    row: dict[str, str], *, default: str = "source_status_not_supplied"
) -> str:
    return row.get("source_status") or row.get("source_coverage_status") or default


def _assumption_by_name() -> dict[str, object]:
    return {assumption.name: assumption for assumption in DEFAULT_RATEWALL_ASSUMPTIONS}


def _path_ratio_classification(ratio: Decimal) -> str:
    if ratio >= Decimal("1"):
        return "ratewall_hit_under_assumptions"
    if ratio >= Decimal("0.5"):
        return "materially_attenuated_under_assumptions"
    return "tightening_mostly_works_under_assumptions"


def _historical_tdc_priority(estimator_key: str) -> int:
    priority = {
        "tdc_tier2_component_anchored_bank_only_ru_flow": 0,
        "tdc_tier2_canonical_depository_institution_mmf_rrp_prop_ru_flow": 1,
        "tdc_base_bank_only_ru_flow": 2,
        "tdc_bank_only_extended_1990": 3,
        "tdc_level_bank_only_sensitivity": 4,
    }
    return priority.get(estimator_key, 999)


def _selected_series_bridge_candidate_comparability_class(
    selected_series_key: str, candidate_estimator_key: str
) -> str:
    if not candidate_estimator_key:
        return "no_bridge_candidate_available_for_quarter"
    if candidate_estimator_key == selected_series_key:
        return "exact_selected_series_match"
    if "bank_only" in candidate_estimator_key and candidate_estimator_key.endswith("_ru_flow"):
        return "bank_only_ru_surrogate_candidate"
    if "broad_depository" in candidate_estimator_key:
        return "broad_depository_scope_shift_candidate"
    if "canonical_depository_institution_mmf_rrp_prop" in candidate_estimator_key:
        return "canonical_di_mmf_rrp_prop_scope_shift_candidate"
    if "extended_1990" in candidate_estimator_key or "level_" in candidate_estimator_key:
        return "legacy_context_surrogate_candidate"
    return "other_bridge_surrogate_candidate"


def _selected_historical_tdc_rows(
    rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    chosen: dict[tuple[str, str], dict[str, str]] = {}
    for row in rows:
        key = (row["quarter"], row["calibration_band"])
        current = chosen.get(key)
        if current is None or _historical_tdc_priority(row["estimator_key"]) < _historical_tdc_priority(
            current["estimator_key"]
        ):
            chosen[key] = row
    return [chosen[key] for key in sorted(chosen)]


def _historical_tdc_guardrail_status_by_path(
    rows: Sequence[dict[str, str]],
) -> dict[tuple[str, str, str], str]:
    grouped: dict[tuple[str, str, str], list[dict[str, str]]] = defaultdict(list)
    for row in rows:
        grouped[(row["quarter"], row["assumption_set"], row["horizon"])].append(row)
    status_by_key: dict[tuple[str, str, str], str] = {}
    for key, group in grouped.items():
        if group and all(item["guardrail_pass"] == "true" for item in group):
            status_by_key[key] = "pass_replace_not_stack_or_memo_only_guardrails_active"
        else:
            status_by_key[key] = "blocked_tdc_double_count_guardrail_failed"
    return status_by_key


def _selected_series_gate_status(selected_meta: dict[str, str]) -> str:
    if selected_meta.get("selection_status") != "selected_from_tdcest_contract":
        return "blocked_no_selected_series_contract"
    if selected_meta.get("selected_quarter_count") in {"", "0"}:
        return "blocked_selected_series_contract_zero_quarters"
    return "pass_selected_series_contract_has_quarter_coverage"


def _historical_panel_gate_status(panel_row: dict[str, str]) -> str:
    coverage_status = panel_row.get(
        "source_coverage_status", "blocked_missing_historical_panel_quarter"
    )
    if coverage_status == "blocked_missing_historical_panel_quarter":
        return coverage_status
    if coverage_status == "coverage_limited_missing_exact_du_ru_split":
        return "context_only_panel_coverage_limited_missing_exact_du_ru_split"
    if coverage_status == "source_backed":
        return "pass_source_backed_historical_panel_context"
    return f"context_only_{coverage_status}"


def _historical_tdc_reduced_form_source_gate_status(
    comparison_row: dict[str, str] | None,
) -> str:
    if comparison_row is None:
        return "blocked_missing_historical_tdc_sidecar_for_quarter"
    source_status = comparison_row.get("historical_tdc_source_coverage_status", "")
    if source_status == "blocked_missing_historical_tdc_sidecar_for_quarter":
        return "blocked_missing_historical_tdc_sidecar_for_quarter"
    if source_status.startswith("source_gate_passed"):
        return "comparison_only_reduced_form_source_gate_passed"
    return "comparison_only_reduced_form_source_gate_not_passed"


def _historical_tdc_overlap_gate_status(
    comparison_row: dict[str, str] | None,
) -> str:
    if comparison_row is None:
        return "blocked_missing_historical_tdc_sidecar_for_quarter"
    overlap_status = comparison_row.get("historical_tdc_overlap_identity_status", "")
    if overlap_status == "blocked_missing_historical_tdc_sidecar_for_quarter":
        return "blocked_missing_historical_tdc_sidecar_for_quarter"
    if overlap_status == "not_available_historical_reduced_form_tdc_no_overlap_bridge":
        return "blocked_overlap_not_proved_for_reduced_form_historical_tdc"
    if overlap_status.startswith("pass"):
        return "pass_overlap_identity_proved_for_historical_tdc"
    return "blocked_historical_tdc_overlap_identity_not_passed"


def _historical_tdc_source_hardening_status(
    *,
    selected_series_gate_status: str,
    historical_panel_gate_status: str,
    historical_tdc_reduced_form_source_gate_status: str,
    historical_tdc_overlap_gate_status: str,
) -> str:
    if historical_tdc_reduced_form_source_gate_status == (
        "blocked_missing_historical_tdc_sidecar_for_quarter"
    ):
        return "blocked_missing_reduced_form_sidecar_for_quarter"
    blockers = []
    if selected_series_gate_status.startswith("blocked"):
        blockers.append("selected_series_empty")
    if historical_panel_gate_status.startswith("context_only") or historical_panel_gate_status.startswith(
        "blocked"
    ):
        blockers.append("panel_context_limited")
    if historical_tdc_overlap_gate_status.startswith("blocked"):
        blockers.append("overlap_unproved")
    if not blockers:
        return "pass_historical_tdc_source_hardening_ready"
    return "comparison_only_" + "_".join(blockers)


def _split_semicolon_values(value: str) -> list[str]:
    return [item for item in (part.strip() for part in value.split(";")) if item]


def _selected_estimator_bridge_rows_by_quarter(
    rows: Sequence[dict[str, str]],
) -> dict[str, list[dict[str, str]]]:
    by_quarter: dict[str, list[dict[str, str]]] = defaultdict(list)
    for row in rows:
        if row.get("observation_status") != "available":
            continue
        by_quarter[row["quarter"]].append(row)
    return by_quarter


def _source_backed_count(rows: Sequence[dict[str, str]], field: str) -> int:
    return sum(row.get(field) == "source_backed" for row in rows)


def _missing_count(rows: Sequence[dict[str, str]], field: str) -> int:
    return sum(row.get(field) == "missing" for row in rows)


def _maturity_scenario_alias(maturity_scenario: str) -> str:
    aliases = {
        "higher_wam_slower_repricing": "longer_wam_lower_repricing",
        "current_wam_cbo_rate_path": "current_wam_repricing",
        "lower_wam_faster_repricing": "shorter_wam_higher_repricing",
    }
    return aliases.get(maturity_scenario, maturity_scenario)


def _forecast_repricing_share_fallback(maturity_scenario: str) -> Decimal:
    fallback = {
        "longer_wam_lower_repricing": Decimal("0.35"),
        "current_wam_repricing": Decimal("0.4782547774466260410080289217"),
        "shorter_wam_higher_repricing": Decimal("0.60"),
    }
    return fallback.get(_maturity_scenario_alias(maturity_scenario), Decimal("0"))


def _forecast_quarterly_exposure_lookup(
    forecast_wall_ratio_path_rows: Sequence[dict[str, str]],
) -> dict[tuple[str, str, str, str], dict[str, str]]:
    grouped: dict[tuple[str, str, str, str], list[dict[str, str]]] = defaultdict(list)
    for row in forecast_wall_ratio_path_rows:
        key = (
            row["forecast_year"],
            row["mpc_scenario"],
            _maturity_scenario_alias(row["maturity_scenario"]),
            row["holder_scenario"],
        )
        grouped[key].append(row)
    lookup: dict[tuple[str, str, str, str], dict[str, str]] = {}
    for key, rows in grouped.items():
        if not rows:
            continue
        repricing_values = [_decimal_or_zero(row["repricing_share_1y"]) for row in rows]
        debt_gdp_values = [
            _decimal_or_zero(row["projected_debt_held_public_gdp_share"]) for row in rows
        ]
        lookup[key] = {
            "repricing_share_1y": _format_decimal(
                sum(repricing_values, Decimal("0")) / Decimal(len(repricing_values))
            ),
            "projected_debt_held_public_gdp_share": _format_decimal(
                sum(debt_gdp_values, Decimal("0")) / Decimal(len(debt_gdp_values))
            ),
            "quarterly_supporting_row_count": str(len(rows)),
        }
    return lookup


def _path_ratio_direct_component_maps(
    path_ratio_numerator_ledger_rows: Sequence[dict[str, str]],
) -> tuple[
    dict[str, list[dict[str, str]]],
    dict[str, dict[str, str]],
]:
    direct_rows_by_group: dict[str, list[dict[str, str]]] = defaultdict(list)
    dominant_by_group: dict[str, dict[str, str]] = {}
    for row in path_ratio_numerator_ledger_rows:
        if row["direct_vs_memo_role"] != "direct":
            continue
        group_id = row["reconciliation_group_id"]
        direct_rows_by_group[group_id].append(row)
        current = dominant_by_group.get(group_id)
        if current is None or abs(_decimal_or_zero(row["component_value_bil"])) > abs(
            _decimal_or_zero(current["component_value_bil"])
        ):
            dominant_by_group[group_id] = row
    return direct_rows_by_group, dominant_by_group


def _quarter_sort_key(quarter: str) -> tuple[int, int]:
    if not quarter or "Q" not in quarter:
        return (9999, 9)
    year, q = quarter.split("Q", 1)
    try:
        return (int(year), int(q))
    except ValueError:
        return (9999, 9)


def _forecast_reference_priority(row: dict[str, str]) -> tuple[int, str, str, str]:
    mpc_priority = {
        "base_mpc_10pct": 0,
        "low_mpc_5pct": 1,
        "high_mpc_20pct": 2,
    }
    maturity_priority = {
        "current_wam_cbo_rate_path": 0,
        "higher_wam_slower_repricing": 1,
        "lower_wam_faster_repricing": 2,
    }
    holder_priority = {
        "current_holder_distribution": 0,
        "shift_to_domestic_nonbanks": 1,
        "shift_to_banks_foreigners": 2,
    }
    return (
        mpc_priority.get(row["mpc_scenario"], 99),
        maturity_priority.get(row["maturity_scenario"], 99),
        holder_priority.get(row["holder_scenario"], 99),
        row.get(
            "forecast_incremental_path_ratio_row_id",
            f"{row['mpc_scenario']}::{row['maturity_scenario']}::{row['holder_scenario']}",
        ),
    )


def _forecast_pass_through_priority(row: dict[str, str]) -> tuple[int, str]:
    priority = {
        "normal_forward_h0": 0,
        "low_pandemic_exclusion_2020": 1,
        "high_recent_rolling_h0": 2,
        "high_full_sample_h0": 3,
    }
    scenario = row.get("pass_through_scenario", "")
    fallback = row.get(
        "forecast_pass_through_scenario_registry_row_id",
        row.get("forecast_pass_through_scenario_row_id", scenario),
    )
    return (priority.get(scenario, 99), fallback)


