def reference_scenario_object_crosswalk_rows(
    *,
    paper_canonical_scenario_results_rows: Sequence[dict[str, str]],
    condition_frontier_rows: Sequence[dict[str, str]],
    annual_flow_denominator_anchor_registry_rows: Sequence[dict[str, str]],
    runtime_annual_flow_support_offset_scenario_rows: Sequence[dict[str, str]],
    runtime_annual_flow_support_offset_frontier_summary_rows: Sequence[dict[str, str]],
    forecast_holder_tdc_consistency_bridge_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()

    def first(rows: Sequence[dict[str, str]], **criteria: str) -> dict[str, str]:
        for candidate in rows:
            if all(candidate.get(key) == value for key, value in criteria.items()):
                return candidate
        return {}

    def hit_status(value: str, *, label: str) -> str:
        parsed = _decimal_or_none(value)
        if parsed is None:
            return f"{label}_not_applicable"
        return f"{label}_{'hit' if parsed >= Decimal('1') else 'not_hit'}"

    def base_row(
        row_id: str,
        ratio_object_id: str,
        object_family: str,
        source_artifact: str,
        source_row_handle: str,
        period_scope: str,
        scenario_scope: str,
        numerator_bil: str,
        denominator_value: str,
        denominator_unit: str,
        denominator_anchor_id: str,
        denominator_status: str,
        wall_ratio_or_offset: str,
        hit_status_value: str,
        comparison_class: str,
        allowed_use: str,
        blocked_use: str,
        safe_sentence: str,
        claim_boundary: str,
        source_status: str,
    ) -> dict[str, str]:
        return {
            "reference_scenario_object_crosswalk_row_id": (
                f"reference_scenario_object_crosswalk::{row_id}"
            ),
            "reference_case_id": "base_current_reference_case",
            "ratio_object_id": ratio_object_id,
            "object_family": object_family,
            "source_artifact": source_artifact,
            "source_row_handle": source_row_handle,
            "period_scope": period_scope,
            "scenario_scope": scenario_scope,
            "numerator_bil": numerator_bil,
            "denominator_value": denominator_value,
            "denominator_unit": denominator_unit,
            "denominator_anchor_id": denominator_anchor_id,
            "denominator_status": denominator_status,
            "wall_ratio_or_offset": wall_ratio_or_offset,
            "hit_status": hit_status_value,
            "comparison_class": comparison_class,
            "allowed_use": allowed_use,
            "blocked_use": blocked_use,
            "safe_sentence": safe_sentence,
            "claim_boundary": claim_boundary,
            "source_status": source_status,
            "canonical_ratio_entry": "false",
            **disabled,
        }

    static = first(
        paper_canonical_scenario_results_rows,
        assumption_set="base_current_100bps",
    )
    static_frontier = first(
        condition_frontier_rows,
        assumption_set="base_current_100bps",
    )
    static_denominator = _decimal_or_zero(
        static_frontier.get("required_countervailing_for_hit_bil", "")
    )
    static_gap = _decimal_or_zero(static_frontier.get("remaining_gap_to_wall_bil", ""))
    static_numerator = max(Decimal("0"), static_denominator - static_gap)

    runtime_frontier = first(
        runtime_annual_flow_support_offset_frontier_summary_rows,
        forecast_year="2026",
        denominator_source_id="literature_annual_flow_bridge_candidate",
    )
    runtime_reference = first(
        runtime_annual_flow_support_offset_scenario_rows,
        runtime_support_offset_row_id=runtime_frontier.get(
            "reference_runtime_support_offset_row_id", ""
        ),
    )
    forecast = first(
        forecast_holder_tdc_consistency_bridge_rows,
        forecast_year="2026",
        mpc_scenario="base_mpc_10pct",
        maturity_scenario="current_wam_cbo_rate_path",
        holder_scenario="current_holder_distribution",
    )
    h8_anchor = first(
        annual_flow_denominator_anchor_registry_rows,
        denominator_source_id="bounded_h8_overlay_review_center",
    )

    rows = [
        base_row(
            "0001",
            "rw_legacy_static_assumption_mode",
            "legacy_static_assumption_mode_sensitivity",
            "ratewall_paper_canonical_scenario_results.csv",
            static.get("assumption_set", "base_current_100bps"),
            "static_one_year",
            "base_current_100bps",
            _format_decimal(static_numerator),
            static_frontier.get("required_countervailing_for_hit_bil", ""),
            "static_conventional_drag_bil_implied_by_assumption_set",
            "legacy_assumption_anchor_base_current_100bps",
            "legacy_assumption_mode_sensitivity_only",
            static.get("ratewall_offset_ratio", ""),
            hit_status(static.get("ratewall_offset_ratio", ""), label="static"),
            "legacy_static_not_commensurate_without_crosswalk",
            "static_assumption_mode_reference",
            "runtime_default;forecast_primary;empirical_threshold_claim",
            (
                "The static base row is a legacy Assumption Mode reference "
                "and does not use the empirical annual-flow denominator. "
                f"{TWO_HEADLINE_CROSSWALK_CLAIM_BOUNDARY}"
            ),
            "reference_crosswalk_static_assumption_mode",
            "pass_static_reference_crosswalked",
        ),
        base_row(
            "0002",
            "rw_runtime_support_offset_af_fixed",
            "runtime_empirical_annual_flow",
            "ratewall_runtime_annual_flow_support_offset_frontier_summary.csv",
            runtime_frontier.get("reference_runtime_support_offset_row_id", ""),
            "forecast_year_2026",
            "base_mpc_10pct/current_wam_cbo_rate_path/current_holder_distribution",
            runtime_reference.get("numerator_total_bil", ""),
            runtime_frontier.get("reference_denominator_center_pp_gdp", ""),
            "pp_gdp_per_100bp_year",
            "literature_annual_flow_bridge_candidate",
            "primary_empirical_annual_flow_runtime_anchor",
            runtime_frontier.get("reference_support_offset_100bp_year_equivalent", ""),
            hit_status(
                runtime_frontier.get(
                    "reference_support_offset_100bp_year_equivalent", ""
                ),
                label="runtime",
            ),
            "runtime_empirical_not_static_or_forecast",
            "runtime_support_offset_reference",
            (
                "canonical_rw_y;historical_primary;forecast_primary;"
                "Evidence_Mode;denominator_prior;empirical_threshold_claim"
            ),
            (
                "The runtime reference row uses the 0.776 pp GDP "
                "empirical annual-flow anchor only for runtime support-offset "
                "diagnostics; it is not the static headline, forecast "
                "headline, canonical RW_Y, Evidence Mode, or a denominator-prior "
                "update."
            ),
            "reference_crosswalk_runtime_empirical_annual_flow",
            "pass_runtime_reference_crosswalked",
        ),
        base_row(
            "0003",
            "rw_forecast_tdc_family_bridge",
            "forecast_tdc_family_interest_only",
            "ratewall_forecast_holder_tdc_consistency_bridge.csv",
            "2026/base_mpc_10pct/current_wam_cbo_rate_path/current_holder_distribution",
            "forecast_year_2026",
            "interest_only_support",
            forecast.get("interest_income_current_demand_support_bil", ""),
            forecast.get("conventional_drag_bil", ""),
            "forecast_conventional_drag_bil",
            "forecast_scenario_drag",
            "forecast_scenario_denominator_not_runtime_anchor",
            forecast.get("interest_only_wall_ratio", ""),
            hit_status(forecast.get("interest_only_wall_ratio", ""), label="forecast_interest_only"),
            "forecast_interest_only_not_static_or_runtime",
            "forecast_interest_only_reference",
            "runtime_default;identified_demand_conversion;canonical_rw_y",
            (
                "The forecast interest-only row uses forecast support and drag "
                "objects, not the runtime empirical denominator."
            ),
            "reference_crosswalk_forecast_interest_only",
            "pass_forecast_interest_only_crosswalked",
        ),
        base_row(
            "0004",
            "rw_forecast_tdc_family_bridge",
            "forecast_tdc_family_ex_overlap_support",
            "ratewall_forecast_holder_tdc_consistency_bridge.csv",
            "2026/base_mpc_10pct/current_wam_cbo_rate_path/current_holder_distribution",
            "forecast_year_2026",
            "direct_interest_plus_tdc_ex_overlap_support",
            forecast.get("combined_current_demand_support_bil", ""),
            forecast.get("conventional_drag_bil", ""),
            "forecast_conventional_drag_bil",
            "forecast_scenario_drag",
            "forecast_scenario_denominator_not_runtime_anchor",
            forecast.get("holder_tdc_consistent_wall_ratio", ""),
            hit_status(forecast.get("holder_tdc_consistent_wall_ratio", ""), label="forecast_tdc"),
            "forecast_tdc_family_not_static_or_runtime",
            "forecast_tdc_family_reference",
            "identified_demand_conversion;canonical_rw_y;runtime_default",
            (
                "The TDC-family forecast row adds ex-direct-interest TDC "
                "support under an explicit deposit-demand conversion "
                "assumption. "
                f"{TWO_HEADLINE_CROSSWALK_CLAIM_BOUNDARY}"
            ),
            "reference_crosswalk_forecast_tdc_family",
            "pass_forecast_tdc_reference_crosswalked",
        ),
        base_row(
            "0005",
            "rw_policy_path_review_only",
            "review_only_bounded_h8_overlay",
            "ratewall_annual_flow_denominator_anchor_registry.csv",
            h8_anchor.get("anchor_row_id", "bounded_h8_overlay_review_center"),
            "review_only",
            "bounded_h8_overlay_review_center",
            "",
            h8_anchor.get("anchor_value_pp_gdp", ""),
            "pp_gdp_review_only_not_annual_flow_runtime_anchor",
            "bounded_h8_overlay_review_center",
            "review_only_overlay_not_default_runtime",
            "",
            "review_only_not_wall_ratio",
            "review_only_not_commensurate_without_unit_netting_crosswalk",
            "bounded_h8_overlay_review_only",
            "runtime_default;headline_probability_surface;canonical_rw_y",
            (
                "The bounded H.8 value is indexed as review-only and is not "
                "pooled with the empirical annual-flow runtime denominator."
            ),
            "reference_crosswalk_bounded_h8_review_only",
            "pass_review_only_reference_crosswalked",
        ),
    ]
    return rows


