def _active_output_guardrail_status(
    active_output_index_rows: Sequence[dict[str, str]],
    artifact_name: str,
) -> str:
    indexed = {
        row.get("artifact_path", "").rsplit("/", 1)[-1]: row
        for row in active_output_index_rows
    }
    row = indexed.get(artifact_name)
    if row and row.get("active_status") in {"active_main", "active_sensitivity"}:
        return "pass_active_output_index_guardrail"
    return "blocked_missing_or_inactive_output_index_guardrail"


def joint_wall_probability_surface_rows(
    *,
    active_output_index_rows: Sequence[dict[str, str]],
    runtime_annual_flow_support_offset_scenario_rows: Sequence[dict[str, str]],
    forecast_holder_tdc_consistency_bridge_rows: Sequence[dict[str, str]],
    forecast_path_ratio_pass_through_scenario_frontier_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    rows: list[dict[str, str]] = []
    row_number = 1

    def add_row(
        *,
        ratio_object_id: str,
        object_family: str,
        source_artifact: str,
        source_row_handle: str,
        forecast_year: str,
        mpc_scenario: str,
        maturity_scenario: str,
        holder_scenario: str,
        support_variant: str,
        denominator_case: str,
        denominator_anchor_id: str,
        denominator_status: str,
        recipient_demand_axis: str,
        tdc_deposit_conversion_axis: str,
        beta_pass_through_axis: str,
        pass_through_scenario: str,
        pass_through_beta: str,
        numerator_bil: str,
        denominator_value: str,
        denominator_unit: str,
        wall_ratio_or_offset: str,
        allowed_use: str,
        blocked_use: str,
        safe_sentence: str,
        claim_boundary: str,
        source_status: str,
    ) -> None:
        nonlocal row_number
        parsed = _decimal_or_none(wall_ratio_or_offset) or Decimal("0")
        rows.append(
            {
                "joint_wall_probability_surface_row_id": (
                    f"joint_wall_probability_surface::{row_number:05d}"
                ),
                "surface_seed": JOINT_WALL_PROBABILITY_SEED,
                "prior_pack_id": JOINT_WALL_PROBABILITY_PRIOR_PACK,
                "probability_claim_status": JOINT_WALL_PROBABILITY_CLAIM,
                "ratio_object_id": ratio_object_id,
                "object_family": object_family,
                "source_artifact": source_artifact,
                "source_row_handle": source_row_handle,
                "forecast_year": forecast_year,
                "mpc_scenario": mpc_scenario,
                "maturity_scenario": maturity_scenario,
                "holder_scenario": holder_scenario,
                "support_variant": support_variant,
                "denominator_case": denominator_case,
                "denominator_anchor_id": denominator_anchor_id,
                "denominator_status": denominator_status,
                "recipient_demand_axis": recipient_demand_axis,
                "tdc_deposit_conversion_axis": tdc_deposit_conversion_axis,
                "beta_pass_through_axis": beta_pass_through_axis,
                "pass_through_scenario": pass_through_scenario,
                "pass_through_beta": pass_through_beta,
                "numerator_bil": numerator_bil,
                "denominator_value": denominator_value,
                "denominator_unit": denominator_unit,
                "wall_ratio_or_offset": _format_decimal(parsed),
                "wall_hit": str(parsed >= Decimal("1")).lower(),
                "surface_weight": "1",
                "headline_surface_allowed": "true",
                "object_family_index_status": _active_output_guardrail_status(
                    active_output_index_rows, source_artifact
                ),
                "allowed_use": allowed_use,
                "blocked_use": blocked_use,
                "safe_sentence": safe_sentence,
                "claim_boundary": claim_boundary,
                "source_status": source_status,
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )
        row_number += 1

    runtime_denominator_cases = [
        (
            "ci95_low_drag",
            "denominator_ci95_low_pp_gdp",
            "support_offset_100bp_year_equivalent_upper_bound",
        ),
        (
            "center_drag",
            "denominator_center_pp_gdp",
            "support_offset_100bp_year_equivalent",
        ),
        (
            "ci95_high_drag",
            "denominator_ci95_high_pp_gdp",
            "support_offset_100bp_year_equivalent_lower_bound",
        ),
    ]
    runtime_rows = [
        row
        for row in runtime_annual_flow_support_offset_scenario_rows
        if row.get("denominator_source_id") == "literature_annual_flow_bridge_candidate"
        and row.get("default_runtime_anchor") == "true"
        and row.get("effective_runtime_output_allowed") == "true"
    ]
    for source_row in sorted(
        runtime_rows,
        key=lambda row: (
            row.get("forecast_year", ""),
            row.get("mpc_scenario", ""),
            row.get("maturity_scenario", ""),
            row.get("holder_scenario", ""),
        ),
    ):
        for denominator_case, denominator_field, offset_field in runtime_denominator_cases:
            add_row(
                ratio_object_id="rw_runtime_support_offset_af_fixed",
                object_family="runtime_empirical_annual_flow",
                source_artifact="ratewall_runtime_annual_flow_support_offset_scenarios.csv",
                source_row_handle=source_row.get("runtime_support_offset_row_id", ""),
                forecast_year=source_row.get("forecast_year", ""),
                mpc_scenario=source_row.get("mpc_scenario", ""),
                maturity_scenario=source_row.get("maturity_scenario", ""),
                holder_scenario=source_row.get("holder_scenario", ""),
                support_variant="runtime_support_offset_100bp_year_equivalent",
                denominator_case=denominator_case,
                denominator_anchor_id=source_row.get("denominator_source_id", ""),
                denominator_status=source_row.get("denominator_role", ""),
                recipient_demand_axis=source_row.get("mpc_scenario", ""),
                tdc_deposit_conversion_axis="not_applicable_runtime_annual_flow",
                beta_pass_through_axis="not_applicable_runtime_annual_flow",
                pass_through_scenario="not_applicable",
                pass_through_beta="",
                numerator_bil=source_row.get("numerator_total_bil", ""),
                denominator_value=source_row.get(denominator_field, ""),
                denominator_unit="pp_gdp_per_100bp_year",
                wall_ratio_or_offset=source_row.get(offset_field, ""),
                allowed_use="conditional_runtime_named_grid_wall_hit_share",
                blocked_use=(
                    "legacy_static_assumption_mode;bounded_h8_review_only;"
                    "policy_path_review_only;empirical_probability_claim;canonical_rw_y"
                ),
                safe_sentence=(
                    "Runtime rows count named empirical annual-flow support-offset "
                    "cases crossing one 100bp-year equivalent."
                ),
                claim_boundary="joint_probability_runtime_conditional_grid_share",
                source_status=source_row.get("source_status", "")
                or source_row.get("runtime_pairing_status", ""),
            )

    for source_row in sorted(
        forecast_holder_tdc_consistency_bridge_rows,
        key=lambda row: (
            row.get("forecast_year", ""),
            row.get("mpc_scenario", ""),
            row.get("maturity_scenario", ""),
            row.get("holder_scenario", ""),
        ),
    ):
        common = {
            "ratio_object_id": "rw_forecast_tdc_family_bridge",
            "object_family": "forecast_tdc_family",
            "source_artifact": "ratewall_forecast_holder_tdc_consistency_bridge.csv",
            "source_row_handle": "/".join(
                [
                    source_row.get("forecast_year", ""),
                    source_row.get("mpc_scenario", ""),
                    source_row.get("maturity_scenario", ""),
                    source_row.get("holder_scenario", ""),
                ]
            ),
            "forecast_year": source_row.get("forecast_year", ""),
            "mpc_scenario": source_row.get("mpc_scenario", ""),
            "maturity_scenario": source_row.get("maturity_scenario", ""),
            "holder_scenario": source_row.get("holder_scenario", ""),
            "denominator_case": "forecast_conventional_drag",
            "denominator_anchor_id": "forecast_scenario_drag",
            "denominator_status": "forecast_scenario_denominator_not_runtime_anchor",
            "recipient_demand_axis": source_row.get("mpc_scenario", ""),
            "tdc_deposit_conversion_axis": source_row.get(
                "tdc_deposit_balance_current_demand_conversion_assumption", ""
            ),
            "beta_pass_through_axis": "not_applied_forecast_tdc_family_bridge",
            "pass_through_scenario": "not_applicable",
            "pass_through_beta": "",
            "denominator_value": source_row.get("conventional_drag_bil", ""),
            "denominator_unit": "forecast_conventional_drag_bil",
            "allowed_use": "conditional_forecast_tdc_family_named_grid_wall_hit_share",
            "blocked_use": (
                "legacy_static_assumption_mode;bounded_h8_review_only;"
                "policy_path_review_only;identified_demand_conversion;"
                "empirical_probability_claim;canonical_rw_y"
            ),
            "source_status": source_row.get("source_status", ""),
        }
        add_row(
            **common,
            support_variant="interest_only_support",
            numerator_bil=source_row.get("interest_income_current_demand_support_bil", ""),
            wall_ratio_or_offset=source_row.get("interest_only_wall_ratio", ""),
            safe_sentence=(
                "Forecast interest-only rows count named forecast support cases "
                "against forecast conventional drag."
            ),
            claim_boundary="joint_probability_forecast_interest_only_conditional_grid_share",
        )
        add_row(
            **common,
            support_variant="tdc_ex_overlap_support",
            numerator_bil=source_row.get("combined_current_demand_support_bil", ""),
            wall_ratio_or_offset=source_row.get("holder_tdc_consistent_wall_ratio", ""),
            safe_sentence=(
                "Forecast TDC-family rows preserve full TDC while counting only "
                "the ex-overlap support conversion cases crossing the wall."
            ),
            claim_boundary="joint_probability_forecast_tdc_family_conditional_grid_share",
        )

    for source_row in sorted(
        forecast_path_ratio_pass_through_scenario_frontier_rows,
        key=lambda row: (
            row.get("forecast_year", ""),
            row.get("mpc_scenario", ""),
            row.get("maturity_scenario", ""),
            row.get("holder_scenario", ""),
            row.get("pass_through_scenario", ""),
        ),
    ):
        add_row(
            ratio_object_id="rw_forecast_wall_ratio_path",
            object_family="forecast_path_beta_sensitivity",
            source_artifact="ratewall_forecast_path_ratio_pass_through_scenario_frontier.csv",
            source_row_handle=source_row.get(
                "forecast_pass_through_scenario_frontier_row_id", ""
            ),
            forecast_year=source_row.get("forecast_year", ""),
            mpc_scenario=source_row.get("mpc_scenario", ""),
            maturity_scenario=source_row.get("maturity_scenario", ""),
            holder_scenario=source_row.get("holder_scenario", ""),
            support_variant="explicit_pass_through_beta_support",
            denominator_case="forecast_path_denominator",
            denominator_anchor_id="forecast_path_denominator_v1_required",
            denominator_status="forecast_path_denominator_materialized",
            recipient_demand_axis=source_row.get("mpc_scenario", ""),
            tdc_deposit_conversion_axis="not_applicable_explicit_beta_frontier",
            beta_pass_through_axis=source_row.get("pass_through_scenario", ""),
            pass_through_scenario=source_row.get("pass_through_scenario", ""),
            pass_through_beta=source_row.get("pass_through_beta", ""),
            numerator_bil=source_row.get("numerator_total_bil", ""),
            denominator_value=source_row.get("denominator_bil", ""),
            denominator_unit="forecast_path_denominator_bil",
            wall_ratio_or_offset=source_row.get("forecast_incremental_path_ratio", ""),
            allowed_use="conditional_forecast_beta_sensitivity_named_grid_wall_hit_share",
            blocked_use=(
                "runtime_default;legacy_static_assumption_mode;bounded_h8_review_only;"
                "policy_path_review_only;empirical_probability_claim;canonical_rw_y"
            ),
            safe_sentence=(
                "Forecast beta-sensitivity rows are counted separately from "
                "runtime annual-flow and forecast TDC-family rows."
            ),
            claim_boundary="joint_probability_forecast_beta_sensitivity_conditional_grid_share",
            source_status=source_row.get("source_status", ""),
        )

    return rows


def joint_wall_probability_summary_rows(
    *,
    joint_wall_probability_surface_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    grouped: dict[tuple[str, str, str, str, str], list[dict[str, str]]] = defaultdict(list)
    for row in joint_wall_probability_surface_rows:
        grouped[
            (
                row.get("ratio_object_id", ""),
                row.get("object_family", ""),
                row.get("support_variant", ""),
                row.get("denominator_case", ""),
                row.get("prior_pack_id", ""),
            )
        ].append(row)

    summary_rows: list[dict[str, str]] = []
    for idx, (key, rows) in enumerate(sorted(grouped.items()), start=1):
        ratio_object_id, object_family, support_variant, denominator_case, prior_pack_id = key
        values = sorted(
            _decimal_or_none(row.get("wall_ratio_or_offset")) or Decimal("0")
            for row in rows
        )
        hit_rows = [row for row in rows if row.get("wall_hit") == "true"]
        row_count = Decimal(len(rows))
        hit_count = Decimal(len(hit_rows))
        midpoint = len(values) // 2
        if len(values) % 2:
            median = values[midpoint]
        else:
            median = (values[midpoint - 1] + values[midpoint]) / Decimal("2")
        tdc_hits = [
            _decimal_or_none(row.get("tdc_deposit_conversion_axis"))
            for row in hit_rows
            if _decimal_or_none(row.get("tdc_deposit_conversion_axis")) is not None
        ]
        beta_hits = [
            _decimal_or_none(row.get("pass_through_beta"))
            for row in hit_rows
            if _decimal_or_none(row.get("pass_through_beta")) is not None
        ]
        summary_rows.append(
            {
                "joint_wall_probability_summary_row_id": (
                    f"joint_wall_probability_summary::{idx:04d}"
                ),
                "surface_seed": JOINT_WALL_PROBABILITY_SEED,
                "prior_pack_id": prior_pack_id,
                "probability_claim_status": JOINT_WALL_PROBABILITY_CLAIM,
                "ratio_object_id": ratio_object_id,
                "object_family": object_family,
                "support_variant": support_variant,
                "denominator_case": denominator_case,
                "surface_row_count": str(len(rows)),
                "wall_hit_count": str(len(hit_rows)),
                "conditional_wall_hit_share": _format_decimal(hit_count / row_count),
                "minimum_wall_ratio_or_offset": _format_decimal(values[0]),
                "median_wall_ratio_or_offset": _format_decimal(median),
                "maximum_wall_ratio_or_offset": _format_decimal(values[-1]),
                "minimum_tdc_deposit_conversion_hit": (
                    _format_decimal(min(tdc_hits)) if tdc_hits else ""
                ),
                "minimum_beta_pass_through_hit": (
                    _format_decimal(min(beta_hits)) if beta_hits else ""
                ),
                "headline_surface_allowed": "true",
                "allowed_use": "conditional_named_grid_wall_hit_share_summary",
                "blocked_use": (
                    "legacy_static_assumption_mode;bounded_h8_review_only;"
                    "policy_path_review_only;empirical_probability_claim;"
                    "posterior_probability_claim;canonical_rw_y"
                ),
                "safe_sentence": (
                    "This row reports the share of named grid cases crossing "
                    "the wall within one object family and support variant."
                ),
                "claim_boundary": "joint_probability_summary_conditional_grid_share",
                "source_status": "pass_summary_from_joint_wall_probability_surface",
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )
    return summary_rows


