def historical_tdc_selected_series_bridge_alignment_rows(
    *,
    historical_tdc_source_admission_targeting_rows: Sequence[dict[str, str]],
    tdcest_historical_estimator_bridge_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "historical_tdc_selected_series_bridge_alignment_nonheadline"
    bridge_rows_by_quarter = _selected_estimator_bridge_rows_by_quarter(
        tdcest_historical_estimator_bridge_rows
    )
    rows: list[dict[str, str]] = []
    for targeting_row in historical_tdc_source_admission_targeting_rows:
        quarter = targeting_row["quarter"]
        quarter_bridge_rows = bridge_rows_by_quarter.get(quarter, [])
        available_keys = sorted(
            {row.get("estimator_key", "") for row in quarter_bridge_rows if row.get("estimator_key")}
        )
        selected_series_available = (
            targeting_row["selected_series_bridge_available_for_quarter"] == "true"
        )
        bridge_alignment_status = (
            "pass_selected_series_bridge_aligned_for_quarter"
            if selected_series_available
            else (
                "blocked_selected_series_bridge_alignment_missing_but_fallback_available"
                if targeting_row["fallback_bridge_estimator_key"]
                else "blocked_no_bridge_alignment_or_fallback_for_quarter"
            )
        )
        bridge_alignment_gap = (
            ""
            if selected_series_available
            else "selected_series_key_absent_from_estimator_bridge_for_quarter"
        )
        rows.append(
            {
                "historical_tdc_selected_series_bridge_alignment_row_id": (
                    "historical_tdc_selected_series_bridge_alignment::"
                    f"{quarter}"
                ),
                "ratio_object_id": "rw_historical_wall_ratio_path",
                "quarter": quarter,
                "linked_targeting_row_id": targeting_row[
                    "historical_tdc_source_admission_targeting_row_id"
                ],
                "selected_series_key": targeting_row["selected_series_key"],
                "selected_series_status": targeting_row["selected_series_status"],
                "selected_series_quarter_count": targeting_row[
                    "selected_series_quarter_count"
                ],
                "available_bridge_estimator_count": str(len(available_keys)),
                "available_bridge_estimator_keys": ";".join(available_keys),
                "selected_series_bridge_status": targeting_row[
                    "selected_series_bridge_status"
                ],
                "selected_series_bridge_available_for_quarter": targeting_row[
                    "selected_series_bridge_available_for_quarter"
                ],
                "fallback_bridge_estimator_key": targeting_row[
                    "fallback_bridge_estimator_key"
                ],
                "fallback_bridge_estimator_status": targeting_row[
                    "fallback_bridge_estimator_status"
                ],
                "bridge_alignment_status": bridge_alignment_status,
                "bridge_alignment_gap": bridge_alignment_gap,
                "next_bridge_alignment_action": (
                    "bridge_selected_series_contract_key_to_estimator_bridge"
                    if not selected_series_available
                    else "selected_series_bridge_alignment_already_present"
                ),
                "allowed_use": "historical_tdc_bridge_alignment_only",
                "blocked_use": (
                    "historical_default_headline_tdc_promotion;runtime_default;canonical_rw_y"
                ),
                "exact_blocker": targeting_row["selected_series_bridge_status"],
                "claim_boundary": claim_boundary,
                "source_status": targeting_row["source_status"],
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )
    return rows


def historical_tdc_admission_feasibility_summary_rows(
    *,
    historical_tdc_source_admission_targeting_rows: Sequence[dict[str, str]],
    historical_tdc_selected_series_bridge_alignment_rows: Sequence[dict[str, str]],
    historical_tdc_source_backed_only_eligibility_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "historical_tdc_admission_feasibility_summary_nonheadline"
    bridge_by_quarter = {
        row["quarter"]: row
        for row in historical_tdc_selected_series_bridge_alignment_rows
    }
    eligibility_by_quarter = {
        row["quarter"]: row
        for row in historical_tdc_source_backed_only_eligibility_rows
    }
    rows: list[dict[str, str]] = []
    for targeting_row in historical_tdc_source_admission_targeting_rows:
        quarter = targeting_row["quarter"]
        bridge_row = bridge_by_quarter[quarter]
        eligibility_row = eligibility_by_quarter[quarter]
        bridge_failure = bridge_row["bridge_alignment_status"]
        panel_failure = targeting_row["historical_panel_gate_status"]
        overlap_failure = targeting_row["historical_tdc_overlap_gate_status"]
        secondary = []
        if panel_failure.startswith("context_only") or panel_failure.startswith("blocked"):
            secondary.append("panel_gap")
        if overlap_failure.startswith("blocked"):
            secondary.append("overlap_gap")
        if bridge_failure.startswith("blocked"):
            primary = "selected_series_bridge_failure"
        elif secondary:
            primary = secondary[0]
        else:
            primary = "no_material_admission_blocker"
        rows.append(
            {
                "historical_tdc_admission_feasibility_row_id": (
                    f"historical_tdc_admission_feasibility::{quarter}"
                ),
                "ratio_object_id": "rw_historical_wall_ratio_path",
                "quarter": quarter,
                "linked_targeting_row_id": targeting_row[
                    "historical_tdc_source_admission_targeting_row_id"
                ],
                "linked_bridge_alignment_row_id": bridge_row[
                    "historical_tdc_selected_series_bridge_alignment_row_id"
                ],
                "linked_source_backed_only_eligibility_row_id": eligibility_row[
                    "historical_tdc_source_backed_only_eligibility_row_id"
                ],
                "selected_series_bridge_failure_status": bridge_failure,
                "panel_gap_failure_status": panel_failure,
                "overlap_failure_status": overlap_failure,
                "primary_blocker_family": primary,
                "secondary_blocker_families": ";".join(secondary),
                "source_backed_only_candidate_status": eligibility_row[
                    "source_backed_only_candidate_status"
                ],
                "admission_feasibility_status": (
                    "blocked_selected_series_bridge_then_panel_overlap"
                    if bridge_failure.startswith("blocked")
                    else (
                        "blocked_panel_or_overlap_after_bridge"
                        if secondary
                        else "pass_nonheadline_admission_feasible"
                    )
                ),
                "next_feasibility_action": targeting_row["next_source_admission_action"],
                "allowed_use": "historical_tdc_admission_feasibility_summary_only",
                "blocked_use": (
                    "historical_default_headline_tdc_promotion;runtime_default;canonical_rw_y"
                ),
                "exact_blocker": targeting_row["exact_blocker"],
                "claim_boundary": claim_boundary,
                "source_status": targeting_row["source_status"],
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )
    return rows


def historical_tdc_source_backed_companion_candidate_rows(
    *,
    historical_tdc_admission_feasibility_summary_rows: Sequence[dict[str, str]],
    historical_tdc_source_backed_only_eligibility_rows: Sequence[dict[str, str]],
    historical_incremental_path_ratio_tdc_comparison_rows: Sequence[dict[str, str]],
    historical_tdc_source_admission_targeting_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "historical_tdc_source_backed_companion_candidate_nonheadline"
    eligibility_by_quarter = {
        row["quarter"]: row for row in historical_tdc_source_backed_only_eligibility_rows
    }
    targeting_by_quarter = {
        row["quarter"]: row for row in historical_tdc_source_admission_targeting_rows
    }
    comparison_by_quarter = {
        row["quarter"]: row
        for row in historical_incremental_path_ratio_tdc_comparison_rows
        if row["calibration_band"] == "base"
    }
    rows: list[dict[str, str]] = []
    for feasibility_row in historical_tdc_admission_feasibility_summary_rows:
        quarter = feasibility_row["quarter"]
        eligibility_row = eligibility_by_quarter[quarter]
        targeting_row = targeting_by_quarter[quarter]
        comparison_row = comparison_by_quarter.get(quarter)
        candidate_allowed = (
            feasibility_row["admission_feasibility_status"]
            == "pass_nonheadline_admission_feasible"
            and eligibility_row["source_backed_only_candidate_status"]
            == "pass_source_backed_only_candidate_eligible"
        )
        rows.append(
            {
                "historical_tdc_source_backed_companion_candidate_row_id": (
                    "historical_tdc_source_backed_companion_candidate::"
                    f"{quarter}"
                ),
                "ratio_object_id": "rw_historical_wall_ratio_path",
                "quarter": quarter,
                "linked_feasibility_row_id": feasibility_row[
                    "historical_tdc_admission_feasibility_row_id"
                ],
                "linked_tdc_comparison_row_id": (
                    "" if comparison_row is None else comparison_row["historical_incremental_path_ratio_tdc_comparison_row_id"]
                ),
                "selected_series_key": targeting_row["selected_series_key"],
                "fallback_bridge_estimator_key": targeting_row[
                    "fallback_bridge_estimator_key"
                ],
                "source_backed_only_candidate_status": eligibility_row[
                    "source_backed_only_candidate_status"
                ],
                "companion_candidate_status": (
                    "nonheadline_source_backed_historical_tdc_candidate_available"
                    if candidate_allowed
                    else "blocked_nonheadline_source_backed_historical_tdc_candidate"
                ),
                "companion_candidate_numerator_bil": (
                    ""
                    if not candidate_allowed or comparison_row is None
                    else comparison_row["candidate_tdc_adjusted_numerator_bil"]
                ),
                "companion_candidate_ratio_reference": (
                    ""
                    if not candidate_allowed or comparison_row is None
                    else comparison_row["candidate_tdc_adjusted_ratio"]
                ),
                "allowed_use": "historical_tdc_source_backed_companion_candidate_only",
                "blocked_use": (
                    "historical_default_headline_tdc_promotion;runtime_default;canonical_rw_y"
                ),
                "exact_blocker": feasibility_row["exact_blocker"],
                "claim_boundary": claim_boundary,
                "source_status": feasibility_row["source_status"],
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )
    return rows


def historical_tdc_selected_series_bridge_remediation_rows(
    *,
    historical_tdc_selected_series_bridge_alignment_rows: Sequence[dict[str, str]],
    historical_tdc_admission_feasibility_summary_rows: Sequence[dict[str, str]],
    tdcest_historical_estimator_bridge_rows: Sequence[dict[str, str]],
    tdc_historical_source_contract_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "historical_tdc_selected_series_bridge_remediation_nonheadline"
    feasibility_by_quarter = {
        row["quarter"]: row for row in historical_tdc_admission_feasibility_summary_rows
    }
    bridge_rows_by_quarter = _selected_estimator_bridge_rows_by_quarter(
        tdcest_historical_estimator_bridge_rows
    )
    source_contract_by_series_key = {
        row["series_key"]: row for row in tdc_historical_source_contract_rows
    }
    rows: list[dict[str, str]] = []
    for bridge_alignment_row in historical_tdc_selected_series_bridge_alignment_rows:
        quarter = bridge_alignment_row["quarter"]
        feasibility_row = feasibility_by_quarter[quarter]
        selected_series_key = bridge_alignment_row["selected_series_key"]
        quarter_bridge_rows = bridge_rows_by_quarter.get(quarter, [])
        unique_candidate_keys = sorted(
            {row.get("estimator_key", "") for row in quarter_bridge_rows if row.get("estimator_key")},
            key=lambda key: (_historical_tdc_priority(key), key),
        )
        candidate_keys = unique_candidate_keys if unique_candidate_keys else [""]
        for index, candidate_key in enumerate(candidate_keys, start=1):
            source_contract_row = source_contract_by_series_key.get(candidate_key, {})
            comparability_class = _selected_series_bridge_candidate_comparability_class(
                selected_series_key, candidate_key
            )
            exact_match = candidate_key == selected_series_key and bool(candidate_key)
            remediation_status = (
                "blocked_selected_series_contract_key_missing_exact_bridge_row"
                if not exact_match
                else "pass_selected_series_contract_key_materialized_in_bridge"
            )
            counterfactual_status = (
                "counterfactual_selected_series_bridge_gap_would_clear"
                if exact_match
                else (
                    "counterfactual_bridge_candidate_available_but_contract_mapping_still_needed"
                    if candidate_key
                    else "counterfactual_no_bridge_candidate_available_for_quarter"
                )
            )
            rows.append(
                {
                    "historical_tdc_selected_series_bridge_remediation_row_id": (
                        "historical_tdc_selected_series_bridge_remediation::"
                        f"{quarter}::{candidate_key or 'no_candidate'}"
                    ),
                    "ratio_object_id": "rw_historical_wall_ratio_path",
                    "quarter": quarter,
                    "linked_bridge_alignment_row_id": bridge_alignment_row[
                        "historical_tdc_selected_series_bridge_alignment_row_id"
                    ],
                    "linked_feasibility_row_id": feasibility_row[
                        "historical_tdc_admission_feasibility_row_id"
                    ],
                    "selected_series_key": selected_series_key,
                    "bridge_candidate_estimator_key": candidate_key,
                    "bridge_candidate_available_for_quarter": (
                        "true" if candidate_key else "false"
                    ),
                    "bridge_candidate_rank_for_quarter": (
                        str(index) if candidate_key else "0"
                    ),
                    "bridge_candidate_estimator_role": source_contract_row.get(
                        "estimator_role",
                        "" if not candidate_key else "bridge_candidate_not_in_source_contract",
                    ),
                    "bridge_candidate_default_classification": source_contract_row.get(
                        "default_classification", ""
                    ),
                    "bridge_candidate_binding_blocker": source_contract_row.get(
                        "binding_blocker", ""
                    ),
                    "bridge_candidate_source_status": source_contract_row.get(
                        "source_status",
                        "" if not candidate_key else "sibling_estimator_bridge_only",
                    ),
                    "bridge_candidate_historical_default_eligible": source_contract_row.get(
                        "historical_default_eligible", "false"
                    ),
                    "bridge_candidate_historical_sensitivity_eligible": source_contract_row.get(
                        "historical_sensitivity_eligible", "false"
                    ),
                    "bridge_candidate_historical_diagnostic_only": source_contract_row.get(
                        "historical_diagnostic_only", "false"
                    ),
                    "bridge_candidate_comparability_class": comparability_class,
                    "selected_series_exact_match": "true" if exact_match else "false",
                    "bridge_remediation_status": remediation_status,
                    "bridge_remediation_counterfactual_status": counterfactual_status,
                    "next_bridge_remediation_action": (
                        "materialize_selected_series_contract_key_in_estimator_bridge"
                        if not candidate_key
                        else "map_selected_series_contract_key_to_bridge_candidate_or_keep_comparison_only"
                    ),
                    "allowed_use": "historical_tdc_selected_series_bridge_remediation_only",
                    "blocked_use": (
                        "historical_default_headline_tdc_promotion;runtime_default;canonical_rw_y"
                    ),
                    "exact_blocker": bridge_alignment_row["exact_blocker"],
                    "claim_boundary": claim_boundary,
                    "source_status": bridge_alignment_row["source_status"],
                    "canonical_ratio_entry": "false",
                    **disabled,
                }
            )
    return rows


