def historical_tdc_post_bridge_admission_status_rows(
    *,
    historical_tdc_admission_candidate_matrix_rows: Sequence[dict[str, str]],
    historical_tdc_selected_series_bridge_execution_rows: Sequence[dict[str, str]],
    historical_tdc_du_ru_methodology_panel_rows: Sequence[dict[str, str]] = (),
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "historical_tdc_post_bridge_admission_status_nonheadline"
    bridge_by_quarter = {
        row["quarter"]: row for row in historical_tdc_selected_series_bridge_execution_rows
    }
    methodology_available_quarters = {
        row["quarter"]
        for row in historical_tdc_du_ru_methodology_panel_rows
        if row.get("available_for_bridge_executed_quarter") == "true"
    }
    rows: list[dict[str, str]] = []
    for admission_row in sorted(
        historical_tdc_admission_candidate_matrix_rows,
        key=lambda row: _quarter_sort_key(row["quarter"]),
    ):
        quarter = admission_row["quarter"]
        bridge_row = bridge_by_quarter[quarter]
        bridge_status = bridge_row["bridge_execution_status"]
        blockers = _split_semicolon_values(
            admission_row["remaining_blockers_after_bridge_only"]
        )
        if quarter in methodology_available_quarters:
            blockers = [
                blocker
                for blocker in blockers
                if blocker != "exact_du_ru_panel_gap"
            ]
        if bridge_status == "pass_selected_series_alias_mapped_to_primary_target_for_available_quarter":
            bridge_after_status = (
                "pass_available_quarter_selected_series_bridge_executed"
            )
            bridge_blocker = ""
            post_bridge_status = (
                "blocked_after_available_bridge_execution_due_to_panel_or_overlap"
                if blockers
                else "pass_available_bridge_execution_panel_overlap_clear_nonheadline"
            )
            stale_status = (
                "pre_bridge_selected_series_blocker_removed_from_active_post_bridge_status"
            )
            source_status = "post_bridge_status_available_quarter"
            exact_blocker = ";".join(blockers)
        else:
            bridge_after_status = "blocked_future_quarter_primary_target_unavailable"
            bridge_blocker = "primary_target_unavailable_for_future_quarter"
            blockers = [bridge_blocker, *blockers]
            post_bridge_status = (
                "blocked_future_primary_target_unavailable_before_panel_overlap_review"
            )
            stale_status = (
                "pre_bridge_selected_series_blocker_replaced_by_future_primary_target_blocker"
            )
            source_status = "future_primary_target_bridge_coverage_missing"
            exact_blocker = ";".join(blockers)

        rows.append(
            {
                "historical_tdc_post_bridge_admission_status_row_id": (
                    f"historical_tdc_post_bridge_admission_status::{quarter}"
                ),
                "ratio_object_id": admission_row["ratio_object_id"],
                "quarter": quarter,
                "linked_admission_candidate_matrix_row_id": admission_row[
                    "historical_tdc_admission_candidate_matrix_row_id"
                ],
                "linked_bridge_execution_row_id": bridge_row[
                    "historical_tdc_selected_series_bridge_execution_row_id"
                ],
                "bridge_execution_status": bridge_status,
                "selected_series_bridge_status_after_execution": bridge_after_status,
                "selected_series_bridge_blocker_after_execution": bridge_blocker,
                "active_post_bridge_blockers": ";".join(blockers),
                "active_post_bridge_blocker_count": str(len(blockers)),
                "post_bridge_candidate_status": post_bridge_status,
                "stale_pre_bridge_blocker_status": stale_status,
                "allowed_use": "historical_tdc_post_bridge_admission_status_only",
                "blocked_use": (
                    "historical_default_headline_tdc_promotion;runtime_default;canonical_rw_y"
                ),
                "exact_blocker": exact_blocker,
                "claim_boundary": claim_boundary,
                "source_status": source_status,
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )
    return rows


def _historical_tdc_bridge_candidate_priority_metadata(
    *,
    estimator_key: str,
    source_status: str,
    comparability_class: str,
    estimator_role: str,
) -> tuple[str, int, str, str]:
    if not estimator_key:
        return (
            "tier7_no_bridge_candidate_available",
            7,
            "materialize_any_quarter_compatible_selected_series_bridge_candidate",
            "bridge_mapping_still_unavailable_until_any_candidate_exists",
        )
    if (
        source_status == "sibling_contract_ingested"
        and comparability_class == "bank_only_ru_surrogate_candidate"
        and estimator_role == "headline_estimator"
    ):
        return (
            "tier1_contract_ingested_bank_only_surrogate",
            1,
            "map_selected_series_contract_key_to_contract_ingested_bank_only_bridge_candidate",
            "bridge_mapping_candidate_available_but_panel_and_overlap_gates_still_bind",
        )
    if comparability_class == "bank_only_ru_surrogate_candidate":
        return (
            "tier2_bank_only_surrogate_without_contract_match",
            2,
            "evaluate_bank_only_surrogate_after_contract_ingested_candidate_review",
            "bridge_mapping_candidate_available_but_contract_lineage_still_missing",
        )
    if comparability_class == "legacy_context_surrogate_candidate":
        return (
            "tier3_legacy_bank_only_context_surrogate",
            3,
            "use_legacy_bank_only_surrogate_only_if_primary_bridge_mapping_stays_unavailable",
            "legacy_context_bridge_candidate_available_but_not_default_lineage_safe",
        )
    if comparability_class == "canonical_di_mmf_rrp_prop_scope_shift_candidate":
        return (
            "tier4_scope_shift_canonical_di_candidate",
            4,
            "defer_scope_shift_candidate_until_bank_only_surrogate_mapping_exhausted",
            "scope_shift_bridge_candidate_available_but changes historical scope",
        )
    if comparability_class == "broad_depository_scope_shift_candidate":
        return (
            "tier5_broad_depository_scope_shift_candidate",
            5,
            "defer_broad_depository_scope_shift_candidate_until_bank_only_and_canonical_scope_candidates_exhausted",
            "broad_scope_bridge_candidate_available_but changes historical scope",
        )
    return (
        "tier6_partial_shell_or_diagnostic_candidate",
        6,
        "keep_partial_shell_candidate_diagnostic_only_until_receipt_side_completion",
        "diagnostic_bridge_candidate_available_but receipt_side_or_scope_incomplete",
    )


def historical_tdc_bridge_candidate_priority_queue_rows(
    *,
    historical_tdc_selected_series_bridge_remediation_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "historical_tdc_bridge_candidate_priority_queue_nonheadline"
    buckets: dict[str, dict[str, object]] = {}
    for source_row in historical_tdc_selected_series_bridge_remediation_rows:
        estimator_key = source_row["bridge_candidate_estimator_key"]
        bucket_key = estimator_key or "__no_bridge_candidate_available__"
        bucket = buckets.setdefault(
            bucket_key,
            {
                "selected_series_key": source_row["selected_series_key"],
                "bridge_candidate_estimator_key": estimator_key,
                "bridge_candidate_estimator_role": source_row[
                    "bridge_candidate_estimator_role"
                ],
                "bridge_candidate_source_status": source_row[
                    "bridge_candidate_source_status"
                ],
                "bridge_candidate_comparability_class": source_row[
                    "bridge_candidate_comparability_class"
                ],
                "bridge_candidate_default_classification": source_row[
                    "bridge_candidate_default_classification"
                ],
                "quarters": set(),
                "ranks": [],
                "rank_one_quarter_count": 0,
                "selected_series_exact_match_found": False,
                "source_status": source_row["source_status"],
            },
        )
        quarter_set = bucket["quarters"]
        assert isinstance(quarter_set, set)
        quarter_set.add(source_row["quarter"])
        rank = source_row["bridge_candidate_rank_for_quarter"]
        if rank:
            rank_value = int(rank)
            rank_list = bucket["ranks"]
            assert isinstance(rank_list, list)
            rank_list.append(rank_value)
            if rank_value == 1:
                bucket["rank_one_quarter_count"] = int(
                    bucket["rank_one_quarter_count"]
                ) + 1
        if source_row["selected_series_exact_match"] == "true":
            bucket["selected_series_exact_match_found"] = True

    ordered_items: list[tuple[tuple[object, ...], dict[str, object]]] = []
    for bucket in buckets.values():
        quarters = sorted(bucket["quarters"], key=_quarter_sort_key)
        ranks = bucket["ranks"]
        average_rank = (
            Decimal(sum(ranks)) / Decimal(len(ranks)) if ranks else Decimal("0")
        )
        priority_tier, bucket_rank, next_action, counterfactual = (
            _historical_tdc_bridge_candidate_priority_metadata(
                estimator_key=str(bucket["bridge_candidate_estimator_key"]),
                source_status=str(bucket["bridge_candidate_source_status"]),
                comparability_class=str(bucket["bridge_candidate_comparability_class"]),
                estimator_role=str(bucket["bridge_candidate_estimator_role"]),
            )
        )
        bucket["quarters_sorted"] = quarters
        bucket["average_rank"] = average_rank
        bucket["priority_tier"] = priority_tier
        bucket["bucket_rank"] = bucket_rank
        bucket["next_action"] = next_action
        bucket["counterfactual"] = counterfactual
        ordered_items.append(
            (
                (
                    bucket_rank,
                    -len(quarters),
                    average_rank,
                    str(bucket["bridge_candidate_estimator_key"]),
                ),
                bucket,
            )
        )

    rows: list[dict[str, str]] = []
    for queue_index, (_sort_key, bucket) in enumerate(sorted(ordered_items), start=1):
        quarters = bucket["quarters_sorted"]
        first_quarter = quarters[0] if quarters else ""
        last_quarter = quarters[-1] if quarters else ""
        estimator_key = str(bucket["bridge_candidate_estimator_key"])
        row_slug = estimator_key or "no_bridge_candidate_available"
        exact_blocker = (
            "blocked_no_bridge_candidate_available_for_quarter"
            if not estimator_key
            else "blocked_selected_series_key_absent_from_estimator_bridge"
        )
        rows.append(
            {
                "historical_tdc_bridge_candidate_priority_row_id": (
                    "historical_tdc_bridge_candidate_priority::"
                    f"{row_slug}"
                ),
                "ratio_object_id": "rw_historical_wall_ratio_path",
                "selected_series_key": str(bucket["selected_series_key"]),
                "bridge_candidate_estimator_key": estimator_key,
                "bridge_candidate_estimator_role": str(
                    bucket["bridge_candidate_estimator_role"]
                ),
                "bridge_candidate_source_status": str(
                    bucket["bridge_candidate_source_status"]
                ),
                "bridge_candidate_comparability_class": str(
                    bucket["bridge_candidate_comparability_class"]
                ),
                "bridge_candidate_default_classification": str(
                    bucket["bridge_candidate_default_classification"]
                ),
                "quarter_coverage_count": str(len(quarters)),
                "first_quarter": first_quarter,
                "last_quarter": last_quarter,
                "average_rank_when_available": _format_decimal(
                    bucket["average_rank"]
                ),
                "rank_one_quarter_count": str(bucket["rank_one_quarter_count"]),
                "selected_series_exact_match_found": (
                    "true" if bucket["selected_series_exact_match_found"] else "false"
                ),
                "priority_tier": str(bucket["priority_tier"]),
                "queue_priority_rank": str(queue_index),
                "next_source_action": str(bucket["next_action"]),
                "counterfactual_if_task_completes": str(bucket["counterfactual"]),
                "allowed_use": "historical_tdc_bridge_candidate_priority_queue_only",
                "blocked_use": (
                    "historical_default_headline_tdc_promotion;runtime_default;canonical_rw_y"
                ),
                "exact_blocker": exact_blocker,
                "claim_boundary": claim_boundary,
                "source_status": str(bucket["source_status"]),
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )
    return rows


def historical_tdc_post_bridge_blocker_queue_rows(
    *,
    historical_tdc_component_gap_registry_rows: Sequence[dict[str, str]],
    historical_tdc_admission_candidate_matrix_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "historical_tdc_post_bridge_blocker_queue_nonheadline"
    remaining_after_bridge = Counter()
    remaining_after_bridge_plus_du_ru = Counter()
    for source_row in historical_tdc_admission_candidate_matrix_rows:
        for blocker in _split_semicolon_values(
            source_row["remaining_blockers_after_bridge_only"]
        ):
            remaining_after_bridge[blocker] += 1
        for blocker in _split_semicolon_values(
            source_row["remaining_blockers_after_bridge_plus_du_ru_panel"]
        ):
            remaining_after_bridge_plus_du_ru[blocker] += 1

    gap_rows_by_component: dict[str, list[dict[str, str]]] = defaultdict(list)
    for gap_row in historical_tdc_component_gap_registry_rows:
        gap_rows_by_component[gap_row["gap_component_id"]].append(gap_row)

    queue_specs = [
        (
            "historical_tdc_overlap_identity",
            "overlap_identity",
            "after_bridge_and_du_ru_panel",
            "prove_direct_interest_overlap_before_historical_tdc_admission",
            "removes_universal_post_bridge_blocker_but_other_panel_fields_still_bind_where_present",
            1,
            "overlap_gap",
        ),
        (
            "treasury_interest_outlays_proxy_bil",
            "other_panel_field_gap",
            "after_bridge_and_du_ru_panel",
            "fill_or_validate_missing_panel_field",
            "reduces_post_bridge_other_panel_tail_but_overlap_still_binds",
            2,
            "other_panel_gap",
        ),
    ]
    rows: list[dict[str, str]] = []
    for component_id, blocker_class, dependency_stage, next_action, counterfactual, bucket_rank, blocker_key in queue_specs:
        component_rows = sorted(
            gap_rows_by_component.get(component_id, []),
            key=lambda row: _quarter_sort_key(row["quarter"]),
        )
        if not component_rows:
            continue
        quarters = [row["quarter"] for row in component_rows]
        rows.append(
            {
                "historical_tdc_post_bridge_blocker_queue_row_id": (
                    "historical_tdc_post_bridge_blocker_queue::"
                    f"{component_id}"
                ),
                "ratio_object_id": "rw_historical_wall_ratio_path",
                "blocker_component_id": component_id,
                "blocker_class": blocker_class,
                "dependency_stage": dependency_stage,
                "blocking_quarter_count": str(len(component_rows)),
                "first_quarter": quarters[0],
                "last_quarter": quarters[-1],
                "bridge_only_quarter_count": str(remaining_after_bridge[blocker_key]),
                "bridge_plus_du_ru_quarter_count": str(
                    remaining_after_bridge_plus_du_ru[blocker_key]
                ),
                "priority_tier": (
                    "tier1_universal_post_bridge_blocker"
                    if bucket_rank == 1
                    else "tier2_other_panel_tail_after_bridge"
                ),
                "queue_priority_rank": str(bucket_rank),
                "next_source_action": next_action,
                "counterfactual_if_task_completes": counterfactual,
                "allowed_use": "historical_tdc_post_bridge_blocker_queue_only",
                "blocked_use": (
                    "historical_default_headline_tdc_promotion;runtime_default;canonical_rw_y"
                ),
                "exact_blocker": component_id,
                "claim_boundary": claim_boundary,
                "source_status": component_rows[0]["source_status"],
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )
    return rows


def historical_tdc_source_work_queue_rows(
    *,
    historical_tdc_bridge_candidate_priority_queue_rows: Sequence[dict[str, str]],
    historical_tdc_du_ru_sensitive_panel_blocker_rows: Sequence[dict[str, str]],
    historical_tdc_post_bridge_blocker_queue_rows: Sequence[dict[str, str]],
    historical_tdc_selected_series_bridge_execution_rows: Sequence[dict[str, str]] = (),
    historical_tdc_du_ru_methodology_panel_rows: Sequence[dict[str, str]] = (),
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "historical_tdc_source_work_queue_nonheadline"
    bridge_row = historical_tdc_bridge_candidate_priority_queue_rows[0]
    bridge_execution_rows = list(historical_tdc_selected_series_bridge_execution_rows)
    bridge_execution_available = bool(bridge_execution_rows)
    blocked_future_bridge_rows = [
        row
        for row in bridge_execution_rows
        if row.get("bridge_execution_status")
        == "blocked_primary_target_unavailable_for_future_quarter"
    ]
    post_bridge_by_component = {
        row["blocker_component_id"]: row
        for row in historical_tdc_post_bridge_blocker_queue_rows
    }
    du_ru_by_field: dict[str, list[dict[str, str]]] = defaultdict(list)
    for source_row in historical_tdc_du_ru_sensitive_panel_blocker_rows:
        du_ru_by_field[source_row["du_ru_sensitive_field"]].append(source_row)
    for rows in du_ru_by_field.values():
        rows.sort(key=lambda row: _quarter_sort_key(row["quarter"]))
    methodology_available_quarters = {
        row["quarter"]
        for row in historical_tdc_du_ru_methodology_panel_rows
        if row.get("available_for_bridge_executed_quarter") == "true"
    }

    def _remaining_du_ru_rows(field: str) -> list[dict[str, str]]:
        return [
            row
            for row in du_ru_by_field[field]
            if row["quarter"] not in methodology_available_quarters
        ]

    task_specs = []
    if not bridge_execution_available:
        task_specs.append(
            (
                "selected_series_bridge_contract_mapping",
                "bridge_mapping",
                "current_primary",
                int(bridge_row["quarter_coverage_count"]),
                bridge_row["first_quarter"],
                bridge_row["last_quarter"],
                bridge_row["historical_tdc_bridge_candidate_priority_row_id"],
                "",
                "Map the selected historical TDC contract key to the top bridge candidate before any headline admission work",
                "bridge_mapping_available_but_panel_and_overlap_gates_still_bind",
                "blocked_selected_series_key_absent_from_estimator_bridge",
                bridge_row["source_status"],
            )
        )
    exact_outlay_rows = _remaining_du_ru_rows("exact_du_ru_outlay_recipient_split")
    exact_security_rows = _remaining_du_ru_rows("exact_du_security_absorption")
    exact_outlay_action = (
        "Extend the TDC-EST RateWall DU/RU methodology export when future "
        "TDC-EST interest and Z.1 absorption inputs publish; no user-supplied "
        "exact values are needed for bridge-executed quarters"
        if methodology_available_quarters
        else "Source exact DU/RU outlay-recipient split inputs after available-quarter bridge execution so reduced-form quarters stop depending on context-only panel coverage"
    )
    exact_security_action = (
        "Extend the TDC-EST RateWall DU/RU methodology export when future Z.1 "
        "absorption inputs publish; no user-supplied security absorption values "
        "are needed for bridge-executed quarters"
        if methodology_available_quarters
        else "Source exact DU security absorption inputs after available-quarter bridge execution so historical TDC no longer relies on context-only security-flow proxies"
    )
    if exact_outlay_rows:
        task_specs.append(
            (
                "exact_du_ru_outlay_recipient_split",
                "exact_du_ru_panel_field",
                (
                    "after_owner_directed_tdcest_z1_methodology_available_quarters"
                    if methodology_available_quarters
                    else "after_available_quarter_bridge_execution"
                ),
                len(exact_outlay_rows),
                exact_outlay_rows[0]["quarter"],
                exact_outlay_rows[-1]["quarter"],
                "",
                "",
                exact_outlay_action,
                "keeps_bridge_executed_du_ru_methodology_closed_future_inputs_pending",
                (
                    "future_quarter_tdcest_z1_methodology_input_unavailable"
                    if methodology_available_quarters
                    else "exact_du_ru_outlay_recipient_split"
                ),
                (
                    "owner_directed_tdcest_z1_methodology_available_future_inputs_pending"
                    if methodology_available_quarters
                    else exact_outlay_rows[0]["source_status"]
                ),
            )
        )
    if exact_security_rows:
        task_specs.append(
            (
                "exact_du_security_absorption",
                "exact_du_ru_panel_field",
                (
                    "after_owner_directed_tdcest_z1_methodology_available_quarters"
                    if methodology_available_quarters
                    else "after_available_quarter_bridge_execution"
                ),
                len(exact_security_rows),
                exact_security_rows[0]["quarter"],
                exact_security_rows[-1]["quarter"],
                "",
                "",
                exact_security_action,
                "keeps_bridge_executed_du_ru_methodology_closed_future_inputs_pending",
                (
                    "future_quarter_tdcest_z1_methodology_input_unavailable"
                    if methodology_available_quarters
                    else "exact_du_security_absorption"
                ),
                (
                    "owner_directed_tdcest_z1_methodology_available_future_inputs_pending"
                    if methodology_available_quarters
                    else exact_security_rows[0]["source_status"]
                ),
            )
        )
    task_specs.extend(
        [
            (
                "foreign_ru_absorption_proxy_bil",
                "ru_context_panel_field",
                "after_available_quarter_bridge_execution",
                len(du_ru_by_field["foreign_ru_absorption_proxy_bil"]),
                du_ru_by_field["foreign_ru_absorption_proxy_bil"][0]["quarter"],
                du_ru_by_field["foreign_ru_absorption_proxy_bil"][-1]["quarter"],
                "",
                "",
                "Fill or validate RU-context absorption coverage where foreign RU proxy gaps still block quarter-level admission after available-quarter bridge execution",
                "removes_ru_context_tail_but_overlap_and_other_panel_gaps_can_still_bind",
                "foreign_ru_absorption_proxy_bil",
                du_ru_by_field["foreign_ru_absorption_proxy_bil"][0]["source_status"],
            ),
        ]
    )
    if blocked_future_bridge_rows:
        task_specs.append(
            (
                "future_primary_target_bridge_coverage",
                "future_primary_target_coverage",
                "after_available_quarter_bridge_execution",
                len(blocked_future_bridge_rows),
                blocked_future_bridge_rows[0]["quarter"],
                blocked_future_bridge_rows[-1]["quarter"],
                "",
                "",
                "Extend locked primary-target bridge coverage before treating 2026Q1-Q2 as bridge-executed historical TDC quarters",
                "removes_future_quarter_bridge_tail_but_panel_and_overlap_gates_still_bind",
                "primary_target_unavailable_for_future_quarter",
                "future_primary_target_bridge_coverage_missing",
            )
        )
    if "historical_tdc_overlap_identity" in post_bridge_by_component:
        task_specs.append(
            (
                "historical_tdc_overlap_identity",
                "overlap_identity",
                "after_available_quarter_bridge_and_panel_fix",
                int(
                    post_bridge_by_component["historical_tdc_overlap_identity"][
                        "blocking_quarter_count"
                    ]
                ),
                post_bridge_by_component["historical_tdc_overlap_identity"][
                    "first_quarter"
                ],
                post_bridge_by_component["historical_tdc_overlap_identity"][
                    "last_quarter"
                ],
                "",
                post_bridge_by_component["historical_tdc_overlap_identity"][
                    "historical_tdc_post_bridge_blocker_queue_row_id"
                ],
                "Prove direct-interest overlap before any nonheadline source-backed historical TDC companion is considered usable",
                post_bridge_by_component["historical_tdc_overlap_identity"][
                    "counterfactual_if_task_completes"
                ],
                "historical_tdc_overlap_identity",
                post_bridge_by_component["historical_tdc_overlap_identity"][
                    "source_status"
                ],
            )
        )
    if "treasury_interest_outlays_proxy_bil" in post_bridge_by_component:
        task_specs.append(
            (
                "treasury_interest_outlays_proxy_bil",
                "other_panel_field",
                "after_available_quarter_bridge_and_panel_fix",
                int(
                    post_bridge_by_component["treasury_interest_outlays_proxy_bil"][
                        "blocking_quarter_count"
                    ]
                ),
                post_bridge_by_component["treasury_interest_outlays_proxy_bil"][
                    "first_quarter"
                ],
                post_bridge_by_component["treasury_interest_outlays_proxy_bil"][
                    "last_quarter"
                ],
                "",
                post_bridge_by_component["treasury_interest_outlays_proxy_bil"][
                    "historical_tdc_post_bridge_blocker_queue_row_id"
                ],
                "Fill or validate the remaining Treasury-interest outlay proxy field after bridge and DU/RU work, because it is the main other-panel tail that still blocks most quarters",
                post_bridge_by_component["treasury_interest_outlays_proxy_bil"][
                    "counterfactual_if_task_completes"
                ],
                "treasury_interest_outlays_proxy_bil",
                post_bridge_by_component["treasury_interest_outlays_proxy_bil"][
                    "source_status"
                ],
            ),
        )
    def _release_blocker_class(
        task_id: str,
        first_quarter: str,
    ) -> str:
        if first_quarter >= "2026Q1":
            return "future_input_tail"
        if task_id == "historical_tdc_overlap_identity":
            return "active_historical_release_blocker"
        return "context_completeness_warning"

    release_priority = {
        "active_historical_release_blocker": 1,
        "context_completeness_warning": 2,
        "future_input_tail": 3,
    }
    task_priority = {
        "historical_tdc_overlap_identity": 1,
        "future_primary_target_bridge_coverage": 2,
        "exact_du_ru_outlay_recipient_split": 3,
        "exact_du_security_absorption": 4,
        "foreign_ru_absorption_proxy_bil": 5,
        "treasury_interest_outlays_proxy_bil": 6,
    }

    rows: list[dict[str, str]] = []
    for queue_rank, (
        task_id,
        task_class,
        dependency_stage,
        quarter_count,
        first_quarter,
        last_quarter,
        linked_bridge_row_id,
        linked_post_bridge_row_id,
        action,
        counterfactual,
        blocker,
        source_status,
    ) in enumerate(
        sorted(
            task_specs,
            key=lambda spec: (
                release_priority[
                    _release_blocker_class(str(spec[0]), str(spec[4]))
                ],
                task_priority.get(str(spec[0]), 99),
                _quarter_sort_key(str(spec[4])),
            ),
        ),
        start=1,
    ):
        release_class = _release_blocker_class(task_id, first_quarter)
        rows.append(
            {
                "historical_tdc_source_work_queue_row_id": (
                    f"historical_tdc_source_work_queue::{task_id}"
                ),
                "ratio_object_id": "rw_historical_wall_ratio_path",
                "queue_priority_rank": str(queue_rank),
                "source_task_id": task_id,
                "source_task_class": task_class,
                "release_blocker_class": release_class,
                "dependency_stage": dependency_stage,
                "blocking_quarter_count": str(quarter_count),
                "first_quarter": first_quarter,
                "last_quarter": last_quarter,
                "linked_bridge_candidate_priority_row_id": linked_bridge_row_id,
                "linked_post_bridge_blocker_queue_row_id": linked_post_bridge_row_id,
                "recommended_source_action": action,
                "completion_counterfactual": counterfactual,
                "allowed_use": "historical_tdc_source_work_queue_only",
                "blocked_use": (
                    "historical_default_headline_tdc_promotion;runtime_default;canonical_rw_y"
                ),
                "exact_blocker": blocker,
                "claim_boundary": claim_boundary,
                "source_status": source_status,
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )
    return rows


def historical_tdc_exact_du_ru_closure_contract_rows(
    *,
    historical_tdc_source_work_queue_rows: Sequence[dict[str, str]],
    historical_tdc_selected_series_bridge_execution_rows: Sequence[dict[str, str]],
    historical_tdc_du_ru_methodology_panel_rows: Sequence[dict[str, str]] = (),
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "historical_tdc_exact_du_ru_closure_contract_nonheadline"
    exact_task_rows = [
        row
        for row in historical_tdc_source_work_queue_rows
        if row["source_task_class"] == "exact_du_ru_panel_field"
    ]
    bridge_status_counts = Counter(
        row["bridge_execution_status"]
        for row in historical_tdc_selected_series_bridge_execution_rows
    )
    available_count = bridge_status_counts[
        "pass_selected_series_alias_mapped_to_primary_target_for_available_quarter"
    ]
    future_blocked_count = bridge_status_counts[
        "blocked_primary_target_unavailable_for_future_quarter"
    ]
    if available_count and future_blocked_count:
        bridge_status = (
            "available_quarter_bridge_execution_complete_future_coverage_blocked"
        )
    elif available_count:
        bridge_status = "available_quarter_bridge_execution_complete"
    else:
        bridge_status = "selected_series_bridge_execution_not_available"
    methodology_available_count = sum(
        row.get("available_for_bridge_executed_quarter") == "true"
        for row in historical_tdc_du_ru_methodology_panel_rows
    )
    if methodology_available_count:
        exact_input_status = (
            "owner_directed_tdcest_z1_methodology_available_for_bridge_executed_quarters"
        )
        closure_status = (
            "pass_for_bridge_executed_quarters_future_coverage_and_overlap_still_bind"
        )
    else:
        exact_input_status = "missing_source_backed_exact_du_ru_values"
        closure_status = "blocked_no_source_backed_exact_du_ru_values_available"

    contract_specs = {
        "exact_du_ru_outlay_recipient_split": {
            "minimum_artifact": (
                "quarter_level_source_backed_treasury_outlay_recipient_split_with_du_ru_tags"
            ),
            "required_measurement": (
                "exact_domestic_user_vs_reserve_user_recipient_classification_for_interest_outlays"
            ),
            "counterfactual": (
                "would_remove_exact_du_ru_outlay_recipient_split_blocker_for_bridge_executed_quarters_but_overlap_future_coverage_and_other_panel_tails_can_still_bind"
            ),
        },
        "exact_du_security_absorption": {
            "minimum_artifact": (
                "quarter_level_source_backed_domestic_user_security_absorption_panel"
            ),
            "required_measurement": (
                "exact_domestic_user_security_absorption_distinct_from_ru_and_context_only_proxy_fields"
            ),
            "counterfactual": (
                "would_remove_exact_du_security_absorption_blocker_for_bridge_executed_quarters_but_overlap_future_coverage_and_other_panel_tails_can_still_bind"
            ),
        },
    }

    rows: list[dict[str, str]] = []
    for row in exact_task_rows:
        task_id = row["source_task_id"]
        spec = contract_specs[task_id]
        rows.append(
            {
                "historical_tdc_exact_du_ru_closure_contract_row_id": (
                    "historical_tdc_exact_du_ru_closure_contract::" f"{task_id}"
                ),
                "ratio_object_id": row["ratio_object_id"],
                "source_task_id": task_id,
                "du_ru_sensitive_field": task_id,
                "closure_contract_class": "exact_du_ru_panel_closure_contract",
                "dependency_stage": row["dependency_stage"],
                "linked_source_work_queue_row_id": row[
                    "historical_tdc_source_work_queue_row_id"
                ],
                "post_bridge_selected_series_status": bridge_status,
                "available_bridge_execution_quarter_count": str(available_count),
                "blocked_future_bridge_quarter_count": str(future_blocked_count),
                "blocking_quarter_count": row["blocking_quarter_count"],
                "first_quarter": row["first_quarter"],
                "last_quarter": row["last_quarter"],
                "source_backed_exact_input_status": exact_input_status,
                "closure_status": closure_status,
                "minimum_acceptable_artifact": spec["minimum_artifact"],
                "required_identity_or_measurement": spec["required_measurement"],
                "completion_counterfactual": spec["counterfactual"],
                "allowed_use": "historical_tdc_exact_du_ru_closure_contract_only",
                "blocked_use": (
                    "historical_default_headline_tdc_promotion;runtime_default;canonical_rw_y"
                ),
                "exact_blocker": row["exact_blocker"],
                "claim_boundary": claim_boundary,
                "source_status": row["source_status"],
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )
    return rows


def historical_tdc_overlap_identity_closure_contract_rows(
    *,
    historical_tdc_source_work_queue_rows: Sequence[dict[str, str]],
    path_ratio_tdc_overlap_audit_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "historical_tdc_overlap_identity_closure_contract_nonheadline"
    historical_audit_rows = [
        row
        for row in path_ratio_tdc_overlap_audit_rows
        if row["source_variant_id"] == "historical_tdc_reduced_form_selected"
    ]
    unavailable_rows = [
        row
        for row in historical_audit_rows
        if row["overlap_identity_status"]
        == "not_available_historical_reduced_form_tdc_no_overlap_bridge"
    ]
    pass_rows = [
        row
        for row in historical_audit_rows
        if row["overlap_identity_status"].startswith("pass")
    ]
    source_row = next(
        (
            row
            for row in historical_tdc_source_work_queue_rows
            if row["source_task_id"] == "historical_tdc_overlap_identity"
        ),
        {},
    )
    overlap_closed = historical_audit_rows and not unavailable_rows
    first_quarter = (
        min((row["quarter"] for row in historical_audit_rows), default="")
        if overlap_closed
        else source_row.get("first_quarter", "")
    )
    last_quarter = (
        max((row["quarter"] for row in historical_audit_rows), default="")
        if overlap_closed
        else source_row.get("last_quarter", "")
    )
    return [
        {
            "historical_tdc_overlap_identity_closure_contract_row_id": (
                "historical_tdc_overlap_identity_closure_contract::"
                "historical_tdc_overlap_identity"
            ),
            "ratio_object_id": source_row.get(
                "ratio_object_id", "rw_historical_wall_ratio_path"
            ),
            "source_task_id": "historical_tdc_overlap_identity",
            "closure_contract_class": "historical_tdc_overlap_identity_contract",
            "dependency_stage": source_row.get(
                "dependency_stage", "closed_by_tdcest_direct_interest_overlap_bridge"
            ),
            "linked_source_work_queue_row_id": source_row.get(
                "historical_tdc_source_work_queue_row_id", ""
            ),
            "linked_post_bridge_blocker_queue_row_id": source_row.get(
                "linked_post_bridge_blocker_queue_row_id", ""
            ),
            "blocking_quarter_count": (
                "0" if overlap_closed else source_row.get("blocking_quarter_count", "")
            ),
            "first_quarter": first_quarter,
            "last_quarter": last_quarter,
            "historical_overlap_audit_row_count": str(len(historical_audit_rows)),
            "unavailable_overlap_audit_row_count": str(len(unavailable_rows)),
            "overlap_source_status": (
                "tdcest_du_interest_overlap_bridge_available"
                if overlap_closed
                else "missing_historical_direct_interest_overlap_bridge"
            ),
            "closure_status": (
                "pass_historical_direct_interest_overlap_identity_materialized"
                if overlap_closed and len(pass_rows) == len(historical_audit_rows)
                else "blocked_historical_reduced_form_tdc_lacks_overlap_identity_bridge"
            ),
            "minimum_acceptable_artifact": (
                "quarter_level_historical_direct_interest_overlap_bridge_linking_tdc_estimator_to_path_numerator_components"
            ),
            "required_identity_or_measurement": (
                "historical_tdc_change_bil_minus_direct_interest_overlap_cashflow_equals_ex_overlap_tdc_basis_by_quarter"
            ),
            "completion_counterfactual": (
                "overlap_identity_closed_for_bridge_executed_historical_tdc_rows"
                if overlap_closed
                else "would_remove_universal_post_bridge_overlap_blocker_after_exact_du_ru_panel_closure_but_future_coverage_and_other_panel_tails_can_still_bind"
            ),
            "allowed_use": (
                "historical_tdc_overlap_identity_closure_contract_only"
            ),
            "blocked_use": (
                "historical_default_headline_tdc_promotion;runtime_default;canonical_rw_y"
            ),
            "exact_blocker": "" if overlap_closed else "historical_tdc_overlap_identity",
            "claim_boundary": claim_boundary,
            "source_status": (
                "historical_overlap_identity_pass_tdcest_du_interest_bridge"
                if overlap_closed
                else "historical_overlap_gap"
            ),
            "canonical_ratio_entry": "false",
            **disabled,
        }
    ]


def _historical_tdc_contract_lineage_status(
    series_key: str, source_contract_by_key: dict[str, dict[str, str]]
) -> str:
    if not series_key:
        return "missing_series_key"
    source_row = source_contract_by_key.get(series_key)
    if source_row is None:
        return "surrogate_only_not_in_source_contract"
    if source_row["source_status"] == "sibling_contract_ingested":
        return "contract_ingested_in_source_contract"
    return "noncontract_lineage_context_only"


def historical_tdc_primary_bridge_target_registry_rows(
    *,
    historical_tdc_bridge_candidate_priority_queue_rows: Sequence[dict[str, str]],
    historical_tdc_selected_series_bridge_alignment_rows: Sequence[dict[str, str]],
    tdc_historical_selected_series_rows: Sequence[dict[str, str]],
    tdc_historical_source_contract_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "historical_tdc_primary_bridge_target_registry_nonheadline"
    selected_row = tdc_historical_selected_series_rows[0]
    source_contract_by_key = {
        row["series_key"]: row for row in tdc_historical_source_contract_rows
    }
    primary_target_row = next(
        row
        for row in historical_tdc_bridge_candidate_priority_queue_rows
        if row["queue_priority_rank"] == "1"
    )
    primary_target_key = primary_target_row["bridge_candidate_estimator_key"]
    alignment_rows = list(historical_tdc_selected_series_bridge_alignment_rows)
    unavailable_quarters = [
        row["quarter"]
        for row in alignment_rows
        if row["fallback_bridge_estimator_key"] == ""
    ]
    matches_count = sum(
        1
        for row in alignment_rows
        if row["fallback_bridge_estimator_key"] == primary_target_key
    )
    differs_count = sum(
        1
        for row in alignment_rows
        if row["fallback_bridge_estimator_key"]
        and row["fallback_bridge_estimator_key"] != primary_target_key
    )
    primary_contract_row = source_contract_by_key.get(primary_target_key, {})
    rows = [
        {
            "historical_tdc_primary_bridge_target_row_id": (
                "historical_tdc_primary_bridge_target::"
                f"{primary_target_key}"
            ),
            "ratio_object_id": "rw_historical_wall_ratio_path",
            "selected_series_key": selected_row["selected_series_key"],
            "selected_series_contract_lineage_status": (
                _historical_tdc_contract_lineage_status(
                    selected_row["selected_series_key"], source_contract_by_key
                )
            ),
            "selected_series_source_status": selected_row["source_status"],
            "selected_series_historical_default_eligible": source_contract_by_key[
                selected_row["selected_series_key"]
            ]["historical_default_eligible"],
            "primary_bridge_target_estimator_key": primary_target_key,
            "primary_target_contract_lineage_status": (
                _historical_tdc_contract_lineage_status(
                    primary_target_key, source_contract_by_key
                )
            ),
            "primary_target_source_status": primary_target_row[
                "bridge_candidate_source_status"
            ],
            "primary_target_estimator_role": primary_target_row[
                "bridge_candidate_estimator_role"
            ],
            "primary_target_historical_default_eligible": primary_contract_row.get(
                "historical_default_eligible", "false"
            ),
            "primary_target_historical_sensitivity_eligible": primary_contract_row.get(
                "historical_sensitivity_eligible", "false"
            ),
            "primary_target_quarter_coverage_count": primary_target_row[
                "quarter_coverage_count"
            ],
            "primary_target_first_quarter": primary_target_row["first_quarter"],
            "primary_target_last_quarter": primary_target_row["last_quarter"],
            "primary_target_missing_quarter_count": str(len(unavailable_quarters)),
            "primary_target_missing_quarters": ";".join(unavailable_quarters),
            "quarter_top_candidate_matches_primary_target_count": str(matches_count),
            "quarter_top_candidate_differs_from_primary_target_count": str(
                differs_count
            ),
            "next_bridge_specific_source_work": (
                "map_selected_series_key_to_primary_contract_ingested_target_for_available_quarters;"
                "materialize_or_define_bridge_target_for_2026Q1_2026Q2"
            ),
            "comparison_only_status_after_bridge_target_lock": (
                "bridge_target_locked_but_historical_tdc_companion_stays_comparison_only_until_panel_and_overlap_gates_close"
            ),
            "allowed_use": "historical_tdc_primary_bridge_target_registry_only",
            "blocked_use": (
                "historical_default_headline_tdc_promotion;runtime_default;canonical_rw_y"
            ),
            "exact_blocker": "blocked_selected_series_key_absent_from_estimator_bridge",
            "claim_boundary": claim_boundary,
            "source_status": selected_row["source_status"],
            "canonical_ratio_entry": "false",
            **disabled,
        }
    ]
    return rows


def historical_tdc_selected_series_primary_target_mapping_plan_rows(
    *,
    historical_tdc_primary_bridge_target_registry_rows: Sequence[dict[str, str]],
    historical_tdc_selected_series_bridge_alignment_rows: Sequence[dict[str, str]],
    historical_tdc_selected_series_bridge_remediation_rows: Sequence[dict[str, str]],
    tdc_historical_source_contract_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = (
        "historical_tdc_selected_series_primary_target_mapping_plan_nonheadline"
    )
    primary_target_row = historical_tdc_primary_bridge_target_registry_rows[0]
    primary_target_key = primary_target_row["primary_bridge_target_estimator_key"]
    linked_priority_row_id = (
        "historical_tdc_bridge_candidate_priority::" f"{primary_target_key}"
    )
    source_contract_by_key = {
        row["series_key"]: row for row in tdc_historical_source_contract_rows
    }
    remediation_by_quarter_candidate = {
        (row["quarter"], row["bridge_candidate_estimator_key"]): row
        for row in historical_tdc_selected_series_bridge_remediation_rows
    }
    rows: list[dict[str, str]] = []
    for alignment_row in historical_tdc_selected_series_bridge_alignment_rows:
        quarter = alignment_row["quarter"]
        primary_candidate_row = remediation_by_quarter_candidate.get(
            (quarter, primary_target_key)
        )
        primary_available = primary_candidate_row is not None
        quarter_top_key = alignment_row["fallback_bridge_estimator_key"]
        quarter_top_matches = primary_available and quarter_top_key == primary_target_key
        if primary_available and quarter_top_matches:
            mapping_status = (
                "planned_primary_target_mapping_same_as_quarter_top_candidate"
            )
            work = "map_selected_series_key_to_primary_target_alias_for_available_quarter"
        elif primary_available:
            mapping_status = (
                "planned_primary_target_mapping_prefers_contract_ingested_target_over_surrogate_only_top_candidate"
            )
            work = (
                "map_selected_series_key_to_contract_ingested_primary_target_even_when_quarter_top_candidate_is_surrogate_only"
            )
        else:
            mapping_status = "blocked_primary_target_unavailable_for_quarter"
            work = (
                "materialize_primary_target_or_define_bridge_alternative_before_selected_series_mapping_for_quarter"
            )
        rows.append(
            {
                "historical_tdc_selected_series_primary_target_mapping_row_id": (
                    "historical_tdc_selected_series_primary_target_mapping::"
                    f"{quarter}"
                ),
                "ratio_object_id": "rw_historical_wall_ratio_path",
                "quarter": quarter,
                "linked_bridge_alignment_row_id": alignment_row[
                    "historical_tdc_selected_series_bridge_alignment_row_id"
                ],
                "linked_bridge_candidate_priority_row_id": linked_priority_row_id,
                "selected_series_key": alignment_row["selected_series_key"],
                "selected_series_contract_lineage_status": (
                    _historical_tdc_contract_lineage_status(
                        alignment_row["selected_series_key"], source_contract_by_key
                    )
                ),
                "primary_bridge_target_estimator_key": primary_target_key,
                "primary_target_contract_lineage_status": (
                    _historical_tdc_contract_lineage_status(
                        primary_target_key, source_contract_by_key
                    )
                ),
                "quarter_top_candidate_estimator_key": quarter_top_key,
                "quarter_top_candidate_contract_lineage_status": (
                    _historical_tdc_contract_lineage_status(
                        quarter_top_key, source_contract_by_key
                    )
                ),
                "primary_target_available_for_quarter": (
                    "true" if primary_available else "false"
                ),
                "primary_target_rank_for_quarter": (
                    ""
                    if primary_candidate_row is None
                    else primary_candidate_row["bridge_candidate_rank_for_quarter"]
                ),
                "quarter_top_candidate_matches_primary_target": (
                    "true" if quarter_top_matches else "false"
                ),
                "mapping_plan_status": mapping_status,
                "bridge_specific_source_work": work,
                "comparison_only_status_after_mapping": (
                    "still_comparison_only_until_panel_and_overlap_gates_close"
                    if primary_available
                    else "still_comparison_only_until_bridge_panel_and_overlap_gates_close"
                ),
                "allowed_use": (
                    "historical_tdc_selected_series_primary_target_mapping_plan_only"
                ),
                "blocked_use": (
                    "historical_default_headline_tdc_promotion;runtime_default;canonical_rw_y"
                ),
                "exact_blocker": alignment_row["exact_blocker"],
                "claim_boundary": claim_boundary,
                "source_status": alignment_row["source_status"],
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )
    return rows


def historical_tdc_selected_series_bridge_execution_rows(
    *,
    historical_tdc_selected_series_primary_target_mapping_plan_rows: Sequence[
        dict[str, str]
    ],
    tdcest_historical_estimator_bridge_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "historical_tdc_selected_series_bridge_execution_nonheadline"
    estimator_by_quarter_key = {
        (row["quarter"], row["estimator_key"]): row
        for row in tdcest_historical_estimator_bridge_rows
    }
    rows: list[dict[str, str]] = []
    for mapping_row in historical_tdc_selected_series_primary_target_mapping_plan_rows:
        quarter = mapping_row["quarter"]
        primary_key = mapping_row["primary_bridge_target_estimator_key"]
        estimator_row = estimator_by_quarter_key.get((quarter, primary_key), {})
        primary_available = bool(estimator_row)
        if primary_available:
            execution_status = (
                "pass_selected_series_alias_mapped_to_primary_target_for_available_quarter"
            )
            companion_status = (
                "bridge_materialized_but_companion_stays_blocked_by_panel_and_overlap_gates"
            )
            comparison_status = (
                "selected_series_alias_bridge_available_comparison_only_until_panel_and_overlap_gates_close"
            )
            exact_blocker = (
                "panel_and_overlap_gates_still_block_historical_tdc_companion_after_bridge_execution"
            )
        else:
            execution_status = (
                "blocked_primary_target_unavailable_for_future_quarter"
            )
            companion_status = (
                "bridge_not_materialized_future_quarter_primary_target_missing"
            )
            comparison_status = (
                "still_comparison_only_until_future_quarter_bridge_panel_and_overlap_gates_close"
            )
            exact_blocker = "blocked_no_bridge_candidate_available_for_quarter"
        if (
            primary_available
            and mapping_row["quarter_top_candidate_estimator_key"]
            and mapping_row["quarter_top_candidate_estimator_key"] != primary_key
        ):
            boundary_status = (
                "contract_ingested_primary_target_preserved_over_surrogate_only_top_candidate"
            )
        elif primary_available:
            boundary_status = "contract_ingested_primary_target_used"
        else:
            boundary_status = "no_primary_target_available_no_surrogate_promotion"
        rows.append(
            {
                "historical_tdc_selected_series_bridge_execution_row_id": (
                    "historical_tdc_selected_series_bridge_execution::"
                    f"{quarter}"
                ),
                "ratio_object_id": "rw_historical_wall_ratio_path",
                "quarter": quarter,
                "linked_mapping_plan_row_id": mapping_row[
                    "historical_tdc_selected_series_primary_target_mapping_row_id"
                ],
                "linked_bridge_alignment_row_id": mapping_row[
                    "linked_bridge_alignment_row_id"
                ],
                "selected_series_key": mapping_row["selected_series_key"],
                "primary_bridge_target_estimator_key": primary_key,
                "primary_target_contract_lineage_status": mapping_row[
                    "primary_target_contract_lineage_status"
                ],
                "bridge_execution_status": execution_status,
                "bridged_estimator_source_artifact": estimator_row.get(
                    "source_artifact", ""
                ),
                "bridged_estimator_value_mil": estimator_row.get(
                    "estimator_value_mil", ""
                ),
                "bridged_estimator_value_bil": estimator_row.get(
                    "estimator_value_bil", ""
                ),
                "bridged_estimator_observation_status": estimator_row.get(
                    "observation_status", ""
                ),
                "modern_tier3_available_for_quarter": estimator_row.get(
                    "modern_tier3_available_for_quarter", ""
                ),
                "contract_vs_surrogate_boundary_status": boundary_status,
                "source_backed_companion_effect_status": companion_status,
                "comparison_only_status_after_execution": comparison_status,
                "allowed_use": (
                    "historical_tdc_selected_series_bridge_execution_only"
                ),
                "blocked_use": (
                    "historical_default_headline_tdc_promotion;runtime_default;canonical_rw_y"
                ),
                "exact_blocker": exact_blocker,
                "claim_boundary": claim_boundary,
                "source_status": (
                    estimator_row.get("source_status")
                    or mapping_row["source_status"]
                ),
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )
    return rows


