def historical_incremental_path_ratio_frontier_summary_rows(
    *,
    historical_incremental_path_ratio_rows: Sequence[dict[str, str]],
    historical_tdc_path_admission_rows: Sequence[dict[str, str]],
    historical_incremental_path_ratio_tdc_comparison_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "historical_incremental_path_ratio_frontier_noncanonical"
    admission_by_quarter = {
        row["quarter"]: row for row in historical_tdc_path_admission_rows
    }
    rows_by_quarter: dict[str, list[dict[str, str]]] = defaultdict(list)
    for row in historical_incremental_path_ratio_rows:
        rows_by_quarter[row["quarter"]].append(row)

    frontier_rank_items: list[tuple[str, Decimal]] = []
    for quarter, rows in rows_by_quarter.items():
        reportable_rows = [
            row
            for row in rows
            if row["row_reportability_status"]
            == "reportable_default_historical_incremental_path_ratio"
        ]
        if reportable_rows:
            frontier_rank_items.append(
                (
                    quarter,
                    max(
                        _decimal_or_zero(row["historical_incremental_path_ratio"])
                        for row in reportable_rows
                    ),
                )
            )
    frontier_ranks = {
        quarter: index + 1
        for index, (quarter, _value) in enumerate(
            sorted(frontier_rank_items, key=lambda item: item[1], reverse=True)
        )
    }

    rows: list[dict[str, str]] = []
    for quarter in sorted(rows_by_quarter, key=_quarter_sort_key):
        quarter_rows = rows_by_quarter[quarter]
        reportable_rows = [
            row
            for row in quarter_rows
            if row["row_reportability_status"]
            == "reportable_default_historical_incremental_path_ratio"
        ]
        transition_rows = [
            row
            for row in quarter_rows
            if row["row_reportability_status"] == "transition_context_not_headline_default"
        ]
        blocked_rows = [
            row
            for row in quarter_rows
            if row["row_reportability_status"] == "blocked_zero_exposure_not_headline_default"
        ]
        base_row = next(
            row for row in quarter_rows if row["calibration_band"] == "base"
        )
        frontier_pool = reportable_rows or transition_rows or blocked_rows
        frontier_row = max(
            frontier_pool,
            key=lambda row: _decimal_or_zero(row["historical_incremental_path_ratio"]),
        )
        admission_row = admission_by_quarter[quarter]
        if reportable_rows:
            frontier_status = "reportable_historical_default_frontier"
            exact_blocker = ""
        elif transition_rows:
            frontier_status = "transition_context_only_historical_frontier"
            exact_blocker = frontier_row["near_zero_guard_status"]
        else:
            frontier_status = "blocked_zero_exposure_historical_frontier"
            exact_blocker = frontier_row["near_zero_guard_status"]
        rows.append(
            {
                "historical_path_ratio_frontier_row_id": (
                    f"historical_path_ratio_frontier::{quarter}"
                ),
                "ratio_object_id": "rw_historical_wall_ratio_path",
                "quarter": quarter,
                "quarter_rank_by_frontier_ratio": (
                    str(frontier_ranks[quarter]) if quarter in frontier_ranks else ""
                ),
                "default_row_count": str(len(quarter_rows)),
                "reportable_default_row_count": str(len(reportable_rows)),
                "transition_default_row_count": str(len(transition_rows)),
                "blocked_default_row_count": str(len(blocked_rows)),
                "base_row_id": base_row["historical_incremental_path_ratio_row_id"],
                "base_band": base_row["calibration_band"],
                "base_ratio": base_row["historical_incremental_path_ratio"],
                "frontier_row_id": frontier_row[
                    "historical_incremental_path_ratio_row_id"
                ],
                "frontier_band": frontier_row["calibration_band"],
                "frontier_ratio": frontier_row["historical_incremental_path_ratio"],
                "frontier_numerator_total_bil": frontier_row["numerator_total_bil"],
                "frontier_denominator_bil": frontier_row["denominator_bil"],
                "frontier_remaining_gap_to_wall_bil": frontier_row[
                    "remaining_gap_to_wall_bil"
                ],
                "frontier_wall_hit": frontier_row["wall_hit_under_incremental_path_ratio"],
                "frontier_distance_classification": frontier_row[
                    "wall_distance_classification"
                ],
                "linked_historical_tdc_admission_row_id": admission_row[
                    "historical_tdc_path_admission_row_id"
                ],
                "linked_historical_tdc_admission_status": admission_row[
                    "historical_tdc_default_headline_admission_status"
                ],
                "linked_historical_tdc_comparison_row_id": admission_row[
                    "linked_tdc_comparison_row_id"
                ],
                "linked_historical_tdc_comparison_status": admission_row[
                    "historical_tdc_comparison_status"
                ],
                "frontier_status": frontier_status,
                "allowed_use": "historical_path_ratio_frontier_summary",
                "blocked_use": (
                    "historical_tdc_default_headline_promotion;runtime_default;canonical_rw_y"
                ),
                "exact_blocker": exact_blocker,
                "claim_boundary": claim_boundary,
                "source_status": frontier_row["source_status"],
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )
    return rows


def forecast_incremental_path_ratio_frontier_summary_rows(
    *,
    forecast_incremental_path_ratio_rows: Sequence[dict[str, str]],
    forecast_incremental_path_ratio_tdc_comparison_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "forecast_incremental_path_ratio_frontier_noncanonical"
    comparison_by_row_id = {
        row["forecast_incremental_path_ratio_row_id"]: row
        for row in forecast_incremental_path_ratio_tdc_comparison_rows
    }
    rows_by_year: dict[str, list[dict[str, str]]] = defaultdict(list)
    for row in forecast_incremental_path_ratio_rows:
        rows_by_year[row["forecast_year"]].append(row)
    max_ranks = {
        year: index + 1
        for index, (year, _value) in enumerate(
            sorted(
                (
                    (
                        year,
                        max(
                            _decimal_or_zero(row["forecast_incremental_path_ratio"])
                            for row in year_rows
                        ),
                    )
                    for year, year_rows in rows_by_year.items()
                ),
                key=lambda item: item[1],
                reverse=True,
            )
        )
    }
    rows: list[dict[str, str]] = []
    for year in sorted(rows_by_year):
        year_rows = rows_by_year[year]
        reference_row = min(year_rows, key=_forecast_reference_priority)
        min_row = min(
            year_rows, key=lambda row: _decimal_or_zero(row["forecast_incremental_path_ratio"])
        )
        max_row = max(
            year_rows, key=lambda row: _decimal_or_zero(row["forecast_incremental_path_ratio"])
        )
        rows.append(
            {
                "forecast_path_ratio_frontier_row_id": (
                    f"forecast_path_ratio_frontier::{year}"
                ),
                "ratio_object_id": "rw_forecast_wall_ratio_path",
                "forecast_year": year,
                "year_rank_by_max_ratio": str(max_ranks[year]),
                "scenario_row_count": str(len(year_rows)),
                "reference_row_id": reference_row[
                    "forecast_incremental_path_ratio_row_id"
                ],
                "reference_mpc_scenario": reference_row["mpc_scenario"],
                "reference_maturity_scenario": reference_row["maturity_scenario"],
                "reference_holder_scenario": reference_row["holder_scenario"],
                "reference_ratio": reference_row["forecast_incremental_path_ratio"],
                "minimum_row_id": min_row["forecast_incremental_path_ratio_row_id"],
                "minimum_mpc_scenario": min_row["mpc_scenario"],
                "minimum_maturity_scenario": min_row["maturity_scenario"],
                "minimum_holder_scenario": min_row["holder_scenario"],
                "minimum_ratio": min_row["forecast_incremental_path_ratio"],
                "maximum_row_id": max_row["forecast_incremental_path_ratio_row_id"],
                "maximum_mpc_scenario": max_row["mpc_scenario"],
                "maximum_maturity_scenario": max_row["maturity_scenario"],
                "maximum_holder_scenario": max_row["holder_scenario"],
                "maximum_ratio": max_row["forecast_incremental_path_ratio"],
                "maximum_remaining_gap_to_wall_bil": max_row[
                    "remaining_gap_to_wall_bil"
                ],
                "any_wall_hit": str(
                    any(
                        row["wall_hit_under_incremental_path_ratio"] == "true"
                        for row in year_rows
                    )
                ).lower(),
                "linked_reference_tdc_comparison_row_id": comparison_by_row_id[
                    reference_row["forecast_incremental_path_ratio_row_id"]
                ]["forecast_incremental_path_ratio_tdc_comparison_row_id"],
                "linked_maximum_tdc_comparison_row_id": comparison_by_row_id[
                    max_row["forecast_incremental_path_ratio_row_id"]
                ]["forecast_incremental_path_ratio_tdc_comparison_row_id"],
                "frontier_status": "reportable_forecast_default_frontier",
                "allowed_use": "forecast_path_ratio_frontier_summary",
                "blocked_use": "runtime_default;canonical_rw_y",
                "exact_blocker": "",
                "claim_boundary": claim_boundary,
                "source_status": reference_row["source_status"],
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )
    return rows


