def forecast_path_ratio_interpretation_rows(
    *,
    forecast_path_ratio_numerator_boundary_rows: Sequence[dict[str, str]],
    forecast_path_ratio_scenario_registry_rows: Sequence[dict[str, str]],
    interest_recipient_leakage_evidence_gap_rows: Sequence[dict[str, str]],
    treasury_recipient_leakage_source_gate_rows: Sequence[dict[str, str]],
    recipient_leakage_design_gate_rows: Sequence[dict[str, str]],
    deposit_pricing_pass_through_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "forecast_path_ratio_interpretation_noncanonical"
    registry_by_id = {
        row["forecast_path_ratio_scenario_registry_row_id"]: row
        for row in forecast_path_ratio_scenario_registry_rows
    }
    evidence_gap_by_component = {
        row["cashflow_component"]: row
        for row in interest_recipient_leakage_evidence_gap_rows
    }
    treasury_gate_row = next(
        (
            row
            for row in treasury_recipient_leakage_source_gate_rows
            if row["gate_block"] == "treasury_recipient_gate_summary"
        ),
        {},
    )
    design_gate_by_component = {
        row["cashflow_component"]: row for row in recipient_leakage_design_gate_rows
    }
    if deposit_pricing_pass_through_rows:
        deposit_pricing_start = min(
            row["quarter"] for row in deposit_pricing_pass_through_rows if row["quarter"]
        )
        deposit_pricing_end = max(
            row["quarter"] for row in deposit_pricing_pass_through_rows if row["quarter"]
        )
        deposit_pricing_coverage = ";".join(
            sorted(
                {
                    row["source_coverage_status"]
                    for row in deposit_pricing_pass_through_rows
                    if row["source_coverage_status"]
                }
            )
        )
    else:
        deposit_pricing_start = ""
        deposit_pricing_end = ""
        deposit_pricing_coverage = ""

    rows: list[dict[str, str]] = []
    for boundary_row in forecast_path_ratio_numerator_boundary_rows:
        registry_row = registry_by_id[
            boundary_row["forecast_path_ratio_scenario_registry_row_id"]
        ]
        component_id = boundary_row["component_id"]
        if component_id == "domestic_nonbank_interest_support":
            evidence_row = evidence_gap_by_component["treasury_interest"]
            design_gate_row = design_gate_by_component["treasury_interest"]
            linked_gap_component = "treasury_interest"
            linked_gate_id = design_gate_row["gate_id"]
            linked_treasury_gate = treasury_gate_row.get("gate_block", "")
            source_context_channel = "treasury_interest_recipient_leakage_context"
            source_context_artifacts = evidence_row["available_source_context_artifacts"]
            source_context_series_or_ids = evidence_row["source_context_series_ids"]
            source_backed_context_status = evidence_row["source_status_class"]
            source_specific_evidence_status = evidence_row[
                "source_specific_evidence_status"
            ]
            source_backed_context_summary = evidence_row["source_evidence_summary"]
            source_backed_context_allowed_use = design_gate_row["allowed_model_use"]
            assumption_conversion_status = (
                "assumption_only_domestic_nonbank_current_spend_share_preserved"
            )
            assumption_parameter_name = "domestic_nonbank_current_spend_share_assumption"
            assumption_parameter_value = boundary_row[
                "domestic_nonbank_current_spend_share_assumption"
            ]
            interpretation_boundary_status = (
                "source_backed_holder_context_assumption_only_current_demand_conversion"
            )
            exact_blocker = design_gate_row["current_gate_status"]
        elif component_id == "bank_retained_margin_support":
            evidence_row = evidence_gap_by_component["iorb_interest"]
            design_gate_row = design_gate_by_component["iorb"]
            linked_gap_component = "iorb_interest"
            linked_gate_id = design_gate_row["gate_id"]
            linked_treasury_gate = ""
            source_context_channel = "bank_reserve_income_and_deposit_pricing_context"
            source_context_artifacts = (
                f"{evidence_row['available_source_context_artifacts']};"
                "ratewall_deposit_pricing_pass_through_context.csv"
            )
            source_context_series_or_ids = evidence_row["source_context_series_ids"]
            source_backed_context_status = evidence_row["source_status_class"]
            source_specific_evidence_status = evidence_row[
                "source_specific_evidence_status"
            ]
            source_backed_context_summary = (
                f"{evidence_row['source_evidence_summary']} "
                f"Deposit-pricing context coverage spans {deposit_pricing_start} to "
                f"{deposit_pricing_end} with statuses {deposit_pricing_coverage}."
            )
            source_backed_context_allowed_use = design_gate_row["allowed_model_use"]
            assumption_conversion_status = (
                "assumption_only_bank_margin_proxy_current_demand_share_preserved"
            )
            assumption_parameter_name = "bank_retained_margin_spend_share_assumption"
            assumption_parameter_value = boundary_row[
                "bank_retained_margin_spend_share_assumption"
            ]
            interpretation_boundary_status = (
                "source_backed_reserve_and_deposit_pricing_context_assumption_only_bank_margin_proxy"
            )
            exact_blocker = design_gate_row["current_gate_status"]
        else:
            linked_gap_component = ""
            linked_gate_id = ""
            linked_treasury_gate = ""
            source_context_channel = "tdc_ex_direct_interest_overlap_contract_internal_bridge"
            source_context_artifacts = (
                "ratewall_forecast_incremental_path_ratio_tdc_comparison.csv;"
                "ratewall_tdc_overlap_audit.csv;"
                "ratewall_forecast_holder_tdc_consistency_bridge.csv"
            )
            source_context_series_or_ids = (
                "tdc_change_bil;tdc_change_ex_overlap_bil;tdc_overlap_identity_status;"
                "double_count_prevention_rule"
            )
            source_backed_context_status = (
                "tdc_ex_direct_interest_overlap_context_not_external_pass_through_beta"
            )
            source_specific_evidence_status = (
                "tdc_ex_direct_interest_overlap_identity_admitted_not_external_deposit_beta"
            )
            source_backed_context_summary = (
                "TDC support uses signed TDC after subtracting direct-interest "
                "overlap as the deposit-balance base; deposit pass-through "
                "remains noncanonical Assumption Mode."
            )
            source_backed_context_allowed_use = (
                "forecast_path_ratio_tdc_ex_direct_interest_overlap_deposit_balance_conversion_context"
            )
            assumption_conversion_status = (
                "assumption_only_deposit_balance_current_demand_conversion"
            )
            assumption_parameter_name = "tdc_deposit_balance_current_demand_conversion"
            assumption_parameter_value = registry_row[
                "tdc_ex_overlap_current_demand_share"
            ]
            interpretation_boundary_status = (
                "tdc_ex_direct_interest_overlap_contract_plus_assumption_only_deposit_balance_conversion"
            )
            exact_blocker = (
                "deposit_balance_conversion_assumption_mode_and_noncanonical_beta"
            )
        rows.append(
            {
                "forecast_path_ratio_interpretation_row_id": (
                    "forecast_path_ratio_interpretation::"
                    f"{boundary_row['forecast_scenario_id']}::{component_id}"
                ),
                "ratio_object_id": "rw_forecast_wall_ratio_path",
                "forecast_path_ratio_numerator_boundary_row_id": boundary_row[
                    "forecast_path_ratio_numerator_boundary_row_id"
                ],
                "forecast_path_ratio_scenario_registry_row_id": boundary_row[
                    "forecast_path_ratio_scenario_registry_row_id"
                ],
                "forecast_path_ratio_decomposition_row_id": boundary_row[
                    "forecast_path_ratio_decomposition_row_id"
                ],
                "forecast_incremental_path_ratio_row_id": boundary_row[
                    "forecast_incremental_path_ratio_row_id"
                ],
                "forecast_year": boundary_row["forecast_year"],
                "forecast_scenario_id": boundary_row["forecast_scenario_id"],
                "channel_conversion_profile_id": boundary_row[
                    "channel_conversion_profile_id"
                ],
                "mpc_scenario": boundary_row["mpc_scenario"],
                "maturity_scenario": boundary_row["maturity_scenario"],
                "holder_scenario": boundary_row["holder_scenario"],
                "component_id": component_id,
                "linked_interest_recipient_gap_component": linked_gap_component,
                "linked_recipient_leakage_design_gate_id": linked_gate_id,
                "linked_treasury_recipient_source_gate_block": linked_treasury_gate,
                "source_context_channel": source_context_channel,
                "source_context_artifacts": source_context_artifacts,
                "source_context_series_or_ids": source_context_series_or_ids,
                "source_backed_context_status": source_backed_context_status,
                "source_specific_evidence_status": source_specific_evidence_status,
                "source_backed_context_summary": source_backed_context_summary,
                "source_backed_context_allowed_use": (
                    source_backed_context_allowed_use
                ),
                "assumption_conversion_status": assumption_conversion_status,
                "assumption_parameter_name": assumption_parameter_name,
                "assumption_parameter_value": assumption_parameter_value,
                "deposit_pass_through_materialization_status": boundary_row[
                    "deposit_pass_through_materialization_status"
                ],
                "bank_margin_vs_depositor_boundary": boundary_row[
                    "bank_margin_vs_depositor_boundary"
                ],
                "interpretation_boundary_status": interpretation_boundary_status,
                "exact_blocker": exact_blocker,
                "allowed_interpretation": boundary_row["allowed_interpretation"],
                "blocked_interpretation": boundary_row["blocked_interpretation"],
                "allowed_use": "forecast_path_ratio_interpretation_registry",
                "blocked_use": "runtime_default;canonical_rw_y",
                "claim_boundary": claim_boundary,
                "source_status": boundary_row["source_status"],
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )
    return rows


