def forecast_treasury_recipient_best_proxy_admission_review_rows(
    *,
    forecast_treasury_recipient_best_proxy_basis_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = (
        "forecast_treasury_recipient_best_proxy_admission_review_noncanonical"
    )
    rows: list[dict[str, str]] = []
    for basis_row in forecast_treasury_recipient_best_proxy_basis_rows:
        proxy_status = basis_row["current_best_proxy_status"]
        proxy_step_id = basis_row["proxy_step_id"]
        if proxy_status == "basis_usable_for_noncanonical_best_proxy":
            source_review = "source_available_cashflow_basis"
            bridge_review = "gross_cashflow_basis_admitted_noncanonical_only"
            admission = "admitted_as_noncanonical_best_proxy_cashflow_basis_only"
            scaffold = "can_feed_future_noncanonical_calculation_scaffold"
            allowed_statement = (
                "Can use TDC-EST Treasury interest outlays as the gross cashflow "
                "basis for a noncanonical best-proxy bridge."
            )
            blocked_statement = (
                "Cannot allocate that cashflow to domestic nonbank current demand "
                "or narrow the Treasury-recipient prior from cashflow basis alone."
            )
            prior_status = "blocked_until_recipient_current_demand_bridge_passes"
        elif proxy_status == "context_usable_for_noncanonical_best_proxy":
            source_review = "source_available_context_only"
            bridge_review = "context_admitted_noncanonical_only"
            admission = "admitted_as_noncanonical_best_proxy_context_only"
            scaffold = "can_feed_future_noncanonical_context_scaffold"
            allowed_statement = (
                "Can use this public source as holder, leakage, or intermediation "
                "context for a noncanonical best-proxy bridge."
            )
            blocked_statement = (
                "Cannot treat the context as final-recipient incidence or current "
                "domestic demand conversion evidence."
            )
            prior_status = "blocked_context_only_no_prior_narrowing"
        elif proxy_status == "routing_exclusion_usable_for_noncanonical_best_proxy":
            source_review = "source_available_routing_exclusion"
            bridge_review = "nonprivate_routing_exclusion_admitted_noncanonical_only"
            admission = "admitted_as_noncanonical_fed_internal_exclusion_only"
            scaffold = "can_feed_future_noncanonical_exclusion_scaffold"
            allowed_statement = (
                "Can keep Federal Reserve internal routing outside private-recipient "
                "Treasury-interest exposure."
            )
            blocked_statement = (
                "Cannot use Fed remittance routing as private recipient current-demand "
                "support."
            )
            prior_status = "not_applicable_exclusion_row_no_prior_narrowing"
        elif proxy_status == "gate_required_before_prior_narrowing":
            source_review = "design_gate_available_fail_closed"
            bridge_review = "design_gate_blocks_prior_narrowing"
            admission = "not_admitted_design_gate_requires_bridge_pass"
            scaffold = "calculation_scaffold_blocked_until_bridge_pass_review"
            allowed_statement = (
                "Can document the fail-closed admission requirement before any "
                "Treasury-recipient prior narrowing."
            )
            blocked_statement = (
                "Cannot admit the best proxy into prior narrowing, canonical runtime, "
                "or welfare/incidence claims without bridge pass review."
            )
            prior_status = "blocked_no_prior_narrowing_or_canonical_promotion"
        else:
            source_review = "contract_gap_documented"
            bridge_review = "not_usable_for_proxy_math"
            admission = "not_admitted_missing_contract_bucket_or_route"
            scaffold = "calculation_scaffold_blocked_by_tdcsim_contract_gap"
            allowed_statement = (
                "Can document the missing TDCSim funding-route split as a boundary "
                "condition for future sibling exports."
            )
            blocked_statement = (
                "Cannot use the current TDCSim Private bucket as a clean "
                "non-deposit-funded domestic-nonbank or MMF-on-RRP route."
            )
            prior_status = "blocked_contract_gap_no_prior_narrowing"

        rows.append(
            {
                "forecast_treasury_recipient_best_proxy_admission_review_row_id": (
                    "forecast_treasury_recipient_best_proxy_admission_review::"
                    f"{int(basis_row['proxy_step_rank']):02d}::{proxy_step_id}"
                ),
                "ratio_object_id": "rw_forecast_wall_ratio_path",
                "component_id": "domestic_nonbank_interest_support",
                "review_rank": basis_row["proxy_step_rank"],
                "review_step_id": proxy_step_id,
                "linked_best_proxy_basis_row_id": basis_row[
                    "forecast_treasury_recipient_best_proxy_basis_row_id"
                ],
                "linked_source_targeting_row_id": basis_row[
                    "linked_source_targeting_row_id"
                ],
                "linked_bridge_row_id": basis_row["linked_bridge_row_id"],
                "linked_bridge_stage_id": basis_row["linked_bridge_stage_id"],
                "proxy_input_family": basis_row["proxy_input_family"],
                "proxy_formula_role": basis_row["proxy_formula_role"],
                "source_availability_review_status": source_review,
                "bridge_use_review_status": bridge_review,
                "current_best_proxy_admission_status": admission,
                "calculation_scaffold_status": scaffold,
                "allowed_statement_now": allowed_statement,
                "blocked_statement_now": blocked_statement,
                "prior_narrowing_status": prior_status,
                "next_review_action": basis_row["next_backend_action"],
                "allowed_use": (
                    "forecast_treasury_recipient_best_proxy_admission_review"
                ),
                "blocked_use": "runtime_default;canonical_rw_y;welfare_incidence_claims",
                "exact_blocker": basis_row["exact_blocker"],
                "claim_boundary": claim_boundary,
                "source_status": basis_row["source_status"],
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )
    return rows


