def forecast_bank_behavior_distribution_bridge_rows(
    *,
    forecast_bank_behavior_bridge_packet_rows: Sequence[dict[str, str]],
    interest_recipient_leakage_bridge_rows: Sequence[dict[str, str]],
    interest_recipient_leakage_evidence_gap_rows: Sequence[dict[str, str]],
    recipient_leakage_design_gate_rows: Sequence[dict[str, str]],
    bank_nim_credit_supply_context_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "forecast_bank_behavior_distribution_bridge_noncanonical"
    packet_by_step = {
        row["packet_step_id"]: row for row in forecast_bank_behavior_bridge_packet_rows
    }
    assumption_row = next(
        row
        for row in interest_recipient_leakage_bridge_rows
        if row["cashflow_component"] == "iorb_interest"
        and row["assumption_set"] == "base_current_100bps"
        and row["horizon"] == "1y"
    )
    evidence_gap_row = next(
        row
        for row in interest_recipient_leakage_evidence_gap_rows
        if row["cashflow_component"] == "iorb_interest"
    )
    design_gate_row = next(
        row
        for row in recipient_leakage_design_gate_rows
        if row["gate_id"] == "recipient_leakage::iorb"
    )
    bank_context_row = next(iter(bank_nim_credit_supply_context_rows))
    summary_row = packet_by_step["forecast_relevance_summary"]

    def _bridge_row(
        *,
        rank: int,
        stage_id: str,
        stage_role: str,
        source_row_origin: str,
        packet_step_id: str,
        linked_interest_component: str,
        linked_design_gate_id: str,
        bridge_target_formula_slot: str,
        gross_cashflow_bil: str,
        current_assumption_share: str,
        current_assumption_support_bil: str,
        leakage_or_noncurrent_share: str,
        available_context_artifacts: str,
        available_context_series_ids: str,
        missing_evidence_family: str,
        next_evidence_target: str,
        evidence_needed_before_prior_narrowing: str,
        bridge_stage_status: str,
        source_status: str,
        exact_blocker: str,
    ) -> dict[str, str]:
        packet_row = packet_by_step[packet_step_id]
        return {
            "forecast_evidence_bridge_row_id": (
                "forecast_evidence_bridge::bank::"
                f"{rank:02d}::{stage_id}"
            ),
            "ratio_object_id": "rw_forecast_wall_ratio_path",
            "bridge_family": "bank_behavior_distribution_bridge",
            "component_id": "bank_retained_margin_support",
            "bridge_stage_rank": str(rank),
            "bridge_stage_id": stage_id,
            "bridge_stage_role": stage_role,
            "source_row_origin": source_row_origin,
            "forecast_evidence_bridge_packet_row_id": packet_row[
                "forecast_evidence_bridge_packet_row_id"
            ],
            "forecast_path_ratio_evidence_targeting_row_id": packet_row[
                "forecast_path_ratio_evidence_targeting_row_id"
            ],
            "forecast_path_ratio_evidence_work_queue_row_id": packet_row[
                "forecast_path_ratio_evidence_work_queue_row_id"
            ],
            "linked_interest_recipient_bridge_component": linked_interest_component,
            "linked_design_gate_id": linked_design_gate_id,
            "bridge_target_formula_slot": bridge_target_formula_slot,
            "current_frontier_binding_status": packet_row[
                "current_frontier_binding_status"
            ],
            "next_backend_action": packet_row["next_backend_action"],
            "work_queue_reason": packet_row["work_queue_reason"],
            "frontier_dependency_years": packet_row["frontier_dependency_years"],
            "gross_cashflow_bil": gross_cashflow_bil,
            "current_assumption_share": current_assumption_share,
            "current_assumption_support_bil": current_assumption_support_bil,
            "leakage_or_noncurrent_share": leakage_or_noncurrent_share,
            "available_context_artifacts": available_context_artifacts,
            "available_context_series_ids": available_context_series_ids,
            "missing_evidence_family": missing_evidence_family,
            "next_evidence_target": next_evidence_target,
            "evidence_needed_before_prior_narrowing": (
                evidence_needed_before_prior_narrowing
            ),
            "bridge_stage_status": bridge_stage_status,
            "allowed_use": "forecast_bank_behavior_distribution_bridge",
            "blocked_use": "runtime_default;canonical_rw_y",
            "exact_blocker": exact_blocker,
            "claim_boundary": claim_boundary,
            "source_status": source_status,
            "canonical_ratio_entry": "false",
            **disabled,
        }

    rows = [
        _bridge_row(
            rank=1,
            stage_id="bridge_summary",
            stage_role="forecast_relevance_summary",
            source_row_origin="evidence_targeting_summary",
            packet_step_id="forecast_relevance_summary",
            linked_interest_component="iorb_interest",
            linked_design_gate_id=design_gate_row["gate_id"],
            bridge_target_formula_slot="bank_behavior_distribution_bridge",
            gross_cashflow_bil="",
            current_assumption_share="",
            current_assumption_support_bil="",
            leakage_or_noncurrent_share="",
            available_context_artifacts=summary_row["available_context_artifacts"],
            available_context_series_ids=summary_row["available_context_series_ids"],
            missing_evidence_family=summary_row["missing_evidence_family"],
            next_evidence_target=summary_row["next_evidence_target"],
            evidence_needed_before_prior_narrowing=summary_row[
                "evidence_needed_before_prior_narrowing"
            ],
            bridge_stage_status="forecast_relevant_bank_bridge_unresolved",
            source_status=summary_row["source_status"],
            exact_blocker=summary_row["exact_blocker"],
        ),
        _bridge_row(
            rank=2,
            stage_id="gross_cashflow_basis",
            stage_role="assumption_mode_bridge_basis",
            source_row_origin="interest_recipient_bridge_assumption",
            packet_step_id="forecast_relevance_summary",
            linked_interest_component=assumption_row["cashflow_component"],
            linked_design_gate_id=design_gate_row["gate_id"],
            bridge_target_formula_slot="gross_iorb_interest_cashflow_bil",
            gross_cashflow_bil=assumption_row["gross_cashflow_bil"],
            current_assumption_share=assumption_row["demand_conversion_share"],
            current_assumption_support_bil=assumption_row[
                "demand_relevant_current_support_bil"
            ],
            leakage_or_noncurrent_share=assumption_row[
                "leakage_or_noncurrent_share"
            ],
            available_context_artifacts=assumption_row["source_specific_artifacts"],
            available_context_series_ids=assumption_row[
                "source_specific_series_or_table_ids"
            ],
            missing_evidence_family=assumption_row["evidence_needed"],
            next_evidence_target=summary_row["next_evidence_target"],
            evidence_needed_before_prior_narrowing=assumption_row["promotion_gate"],
            bridge_stage_status="assumption_mode_basis_preserved_until_bridge_passes",
            source_status=assumption_row["source_status"],
            exact_blocker=design_gate_row["exact_blocker"],
        ),
        _bridge_row(
            rank=3,
            stage_id="reserve_income_context_gap",
            stage_role="evidence_gap_context",
            source_row_origin="interest_recipient_evidence_gap",
            packet_step_id="iorb_interest_evidence_gap",
            linked_interest_component=evidence_gap_row["cashflow_component"],
            linked_design_gate_id=design_gate_row["gate_id"],
            bridge_target_formula_slot="reserve_income_and_deposit_pricing_context",
            gross_cashflow_bil=assumption_row["gross_cashflow_bil"],
            current_assumption_share=assumption_row["demand_conversion_share"],
            current_assumption_support_bil=assumption_row[
                "demand_relevant_current_support_bil"
            ],
            leakage_or_noncurrent_share=assumption_row["leakage_or_noncurrent_share"],
            available_context_artifacts=evidence_gap_row[
                "available_source_context_artifacts"
            ],
            available_context_series_ids=evidence_gap_row[
                "source_context_series_ids"
            ],
            missing_evidence_family=evidence_gap_row[
                "missing_leakage_pass_through_timing_evidence"
            ],
            next_evidence_target=summary_row["next_evidence_target"],
            evidence_needed_before_prior_narrowing=evidence_gap_row["promotion_gate"],
            bridge_stage_status="reserve_pricing_context_only_not_behavior_bridge",
            source_status=evidence_gap_row["source_status"],
            exact_blocker=evidence_gap_row[
                "exact_gate_before_demand_conversion_narrowing"
            ],
        ),
        _bridge_row(
            rank=4,
            stage_id="bank_nim_credit_supply_context",
            stage_role="bank_context_sidecar",
            source_row_origin="bank_nim_credit_supply_context",
            packet_step_id="iorb_interest_evidence_gap",
            linked_interest_component="iorb_interest",
            linked_design_gate_id=design_gate_row["gate_id"],
            bridge_target_formula_slot="retention_distribution_credit_supply_context",
            gross_cashflow_bil="",
            current_assumption_share="",
            current_assumption_support_bil="",
            leakage_or_noncurrent_share="",
            available_context_artifacts=bank_context_row["artifact_name"],
            available_context_series_ids=bank_context_row["source_ids"],
            missing_evidence_family=(
                "bank_distribution_retention_credit_supply_and_timing_bridge_gap"
            ),
            next_evidence_target=summary_row["next_evidence_target"],
            evidence_needed_before_prior_narrowing=summary_row[
                "evidence_needed_before_prior_narrowing"
            ],
            bridge_stage_status="context_sidecar_not_component_bridge",
            source_status="bank_intermediation_context_available_not_bridge",
            exact_blocker=design_gate_row["exact_blocker"],
        ),
        _bridge_row(
            rank=5,
            stage_id="design_gate_closeout",
            stage_role="recipient_leakage_design_gate",
            source_row_origin="recipient_leakage_design_gate",
            packet_step_id="iorb_design_gate",
            linked_interest_component="iorb_interest",
            linked_design_gate_id=design_gate_row["gate_id"],
            bridge_target_formula_slot=(
                "bank_current_demand_conversion_net_of_retention_credit_supply"
            ),
            gross_cashflow_bil="",
            current_assumption_share="",
            current_assumption_support_bil="",
            leakage_or_noncurrent_share="",
            available_context_artifacts=design_gate_row["cashflow_source"],
            available_context_series_ids=design_gate_row[
                "source_context_series_ids"
            ],
            missing_evidence_family=design_gate_row[
                "pass_through_or_retention_context_status"
            ],
            next_evidence_target=design_gate_row[
                "evidence_needed_before_prior_narrowing"
            ],
            evidence_needed_before_prior_narrowing=design_gate_row[
                "evidence_needed_before_prior_narrowing"
            ],
            bridge_stage_status="fail_closed_design_gate",
            source_status="recipient_leakage_design_gate_context_only",
            exact_blocker=design_gate_row["exact_blocker"],
        ),
    ]
    return rows


def final_recipient_current_demand_bridge_attempt_rows(
    *,
    forecast_treasury_recipient_current_demand_evidence_contract_rows: Sequence[
        dict[str, str]
    ],
    forecast_bank_behavior_current_demand_evidence_contract_rows: Sequence[
        dict[str, str]
    ],
    z1_domestic_nonbank_sector_context_rows: Sequence[dict[str, str]],
    mmf_route_split_context_rows: Sequence[dict[str, str]],
    tdcest_monetary_route_bridge_rows: Sequence[dict[str, str]],
    tdcsim_domestic_nonbank_funding_classification_rows: Sequence[dict[str, str]],
    tdcsim_private_route_sensitivity_ingest_rows: Sequence[dict[str, str]],
    holder_allocation_gate_rows: Sequence[dict[str, str]],
    forecast_treasury_beneficial_owner_recipient_bridge_pass_review_rows: Sequence[
        dict[str, str]
    ],
    forecast_bank_behavior_distribution_bridge_pass_review_rows: Sequence[
        dict[str, str]
    ],
    deposit_pricing_pass_through_rows: Sequence[dict[str, str]],
    tdc_rolling_pass_through_context_rows: Sequence[dict[str, str]],
    bank_nim_credit_supply_context_rows: Sequence[dict[str, str]],
    bank_loan_repricing_context_rows: Sequence[dict[str, str]],
    tdcpass_quarterly_panel_rows: Sequence[dict[str, str]] = (),
    fdic_bank_margin_distribution_rows: Sequence[dict[str, str]] = (),
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = (
        "final_recipient_current_demand_bridge_attempt_fail_closed_source_scan"
    )

    def count(rows: Sequence[dict[str, str]], field: str, value: str) -> int:
        return sum(1 for row in rows if row.get(field) == value)

    z1_current_demand_true = count(
        z1_domestic_nonbank_sector_context_rows, "current_demand_eligible", "true"
    )
    mmf_current_demand_true = count(
        mmf_route_split_context_rows, "current_demand_eligible", "true"
    )
    monetary_current_demand_true = count(
        tdcest_monetary_route_bridge_rows, "current_demand_eligible", "true"
    )
    tdcsim_route_contract_present = count(
        tdcsim_domestic_nonbank_funding_classification_rows,
        "tdcsim_route_contract_status",
        "route_contract_present",
    )
    holder_final_owner_ready = count(
        holder_allocation_gate_rows, "final_owner_mapping_ready", "true"
    )
    deposit_pricing_source_backed = count(
        deposit_pricing_pass_through_rows, "source_coverage_status", "source_backed_context"
    )
    bank_pass_review_blocked = count(
        forecast_bank_behavior_distribution_bridge_pass_review_rows,
        "bridge_admission_after_proxy_status",
        "blocked_proxy_values_do_not_clear_current_demand_bridge",
    )
    tdcpass_borrower_fields = [
        "strict_di_loans_nec_private_domestic_borrower_qoq",
        "strict_di_loans_nec_systemwide_borrower_total_qoq",
        "strict_loan_core_plus_private_borrower_qoq",
        "strict_funding_offset_total_qoq",
        "strict_identifiable_net_after_funding_qoq",
        "commercial_industrial_loans_ex_chargeoffs_qoq",
        "consumer_loans_ex_chargeoffs_qoq",
    ]
    tdcpass_borrower_rows = [
        row
        for row in tdcpass_quarterly_panel_rows
        if row.get("quarter")
        and any(row.get(field) not in {"", None} for field in tdcpass_borrower_fields)
    ]
    latest_tdcpass_borrower_row = (
        tdcpass_borrower_rows[-1] if tdcpass_borrower_rows else {}
    )
    tdcpass_latest_quarter = latest_tdcpass_borrower_row.get("quarter", "")
    fdic_margin_rows = [
        row
        for row in fdic_bank_margin_distribution_rows
        if row.get("quarter")
        and row.get("source_status")
        == "fdic_financials_source_backed_aggregate_distribution_route_context"
    ]
    latest_fdic_margin_row = fdic_margin_rows[-1] if fdic_margin_rows else {}
    fdic_latest_quarter = latest_fdic_margin_row.get("quarter", "")

    def treasury_source_scan(source_family: str) -> tuple[str, int, str]:
        if source_family == "gross_cashflow_basis":
            total = len(holder_allocation_gate_rows)
            return (
                (
                    "tdcest_gross_cashflow_basis_present;"
                    f"holder_gate_rows={len(holder_allocation_gate_rows)};"
                    f"final_owner_mapping_ready_rows={holder_final_owner_ready}"
                ),
                total,
                "pass_source_backed_cashflow_context_no_final_recipient_bridge",
            )
        if source_family == "domestic_private_holder_context":
            total = len(z1_domestic_nonbank_sector_context_rows)
            return (
                (
                    f"z1_rows={total};"
                    f"current_demand_eligible_rows={z1_current_demand_true};"
                    f"unknown_or_mixed_m2_rows="
                    f"{count(z1_domestic_nonbank_sector_context_rows, 'm2_scope', 'unknown_or_mixed')};"
                    f"deposit_pass_through_unknown_or_mixed_rows="
                    f"{count(z1_domestic_nonbank_sector_context_rows, 'deposit_pass_through_scope', 'unknown_or_mixed')}"
                ),
                total,
                "pass_source_backed_holder_context_no_final_recipient_split",
            )
        if source_family == "foreign_holder_leakage_context":
            total = len(
                forecast_treasury_beneficial_owner_recipient_bridge_pass_review_rows
            )
            return (
                (
                    f"treasury_pass_review_rows={total};"
                    "foreign_recycling_rows_blocked_pending_beneficial_owner_timing=1;"
                    f"holder_gate_final_owner_ready_rows={holder_final_owner_ready}"
                ),
                total + len(holder_allocation_gate_rows),
                "pass_foreign_context_no_beneficial_owner_recycling_bridge",
            )
        if source_family == "mmf_portfolio_and_repo_context":
            total = len(mmf_route_split_context_rows) + len(
                tdcest_monetary_route_bridge_rows
            )
            return (
                (
                    f"mmf_rows={len(mmf_route_split_context_rows)};"
                    f"mmf_current_demand_eligible_rows={mmf_current_demand_true};"
                    f"mmf_m2_true_rows={count(mmf_route_split_context_rows, 'm2_scope', 'true')};"
                    f"monetary_route_rows={len(tdcest_monetary_route_bridge_rows)};"
                    f"monetary_route_current_demand_eligible_rows={monetary_current_demand_true}"
                ),
                total,
                "pass_mmf_portfolio_context_no_final_investor_or_deposit_route_split",
            )
        if source_family == "fed_internal_routing_exclusion":
            return (
                "fed_internal_routing_is_public_finance_exclusion_context_not_private_recipient_bridge",
                1,
                "pass_public_exclusion_context_no_private_current_demand_bridge",
            )
        if source_family == "current_demand_conversion_gate":
            total = (
                len(z1_domestic_nonbank_sector_context_rows)
                + len(mmf_route_split_context_rows)
                + len(tdcest_monetary_route_bridge_rows)
                + len(holder_allocation_gate_rows)
            )
            admitted = (
                z1_current_demand_true
                + mmf_current_demand_true
                + monetary_current_demand_true
                + holder_final_owner_ready
            )
            return (
                f"admissible_current_demand_or_final_owner_rows={admitted};scanned_rows={total}",
                total,
                "blocked_no_source_backed_current_demand_conversion_rows",
            )
        if source_family == "tdcsim_funding_route_contract_gap":
            total = len(tdcsim_domestic_nonbank_funding_classification_rows)
            bounded_proxy_rows = sum(
                1
                for row in tdcsim_private_route_sensitivity_ingest_rows
                if row.get("bounded_noncanonical_private_route_proxy") == "true"
            )
            blocked = sum(
                1
                for row in tdcsim_domestic_nonbank_funding_classification_rows
                if row.get("tdcsim_route_contract_binding_blocker")
            )
            linked_tdcest_context_row = next(
                (
                    row
                    for row in tdcsim_domestic_nonbank_funding_classification_rows
                    if row.get("linked_tdcest_route_context_row_count", "0") != "0"
                ),
                {},
            )
            source_backed_private_split_rows = sum(
                1
                for row in tdcsim_domestic_nonbank_funding_classification_rows
                if row.get("source_backed_private_bucket_split_status", "").startswith(
                    "pass_"
                )
            )
            route_context_target_rows = sum(
                1
                for row in tdcsim_domestic_nonbank_funding_classification_rows
                if row.get("source_backed_private_bucket_split_status", "").startswith(
                    "source_context_available"
                )
            )
            return (
                (
                    f"tdcsim_classification_rows={total};"
                    f"route_contract_present_rows={tdcsim_route_contract_present};"
                    f"binding_blocker_rows={blocked};"
                    "tdcest_route_context_latest_quarter="
                    f"{linked_tdcest_context_row.get('linked_tdcest_latest_quarter', '')};"
                    "tdcest_route_context_rows="
                    f"{linked_tdcest_context_row.get('linked_tdcest_route_context_row_count', '0')};"
                    "source_backed_private_bucket_split_rows="
                    f"{source_backed_private_split_rows};"
                    "bounded_noncanonical_private_route_proxy_rows="
                    f"{bounded_proxy_rows};"
                    f"route_context_target_rows={route_context_target_rows}"
                ),
                total,
                "pass_route_contract_context_but_private_bucket_split_missing",
            )
        return (
            "source_family_not_matched_to_specific_scan",
            0,
            "blocked_unmatched_source_family",
        )

    def bank_source_scan(source_family: str) -> tuple[str, int, str]:
        if source_family in {
            "gross_iorb_cashflow_basis",
            "reserve_income_and_deposit_pricing_context",
        }:
            total = len(deposit_pricing_pass_through_rows) + len(
                tdc_rolling_pass_through_context_rows
            )
            return (
                (
                    f"deposit_pricing_rows={len(deposit_pricing_pass_through_rows)};"
                    f"deposit_pricing_source_backed_rows={deposit_pricing_source_backed};"
                    f"rolling_pass_through_rows={len(tdc_rolling_pass_through_context_rows)};"
                    f"bank_pass_review_blocked_after_proxy_rows={bank_pass_review_blocked}"
                ),
                total,
                "pass_cashflow_pricing_pass_through_context_no_retained_margin_timing_bridge",
            )
        if source_family == "bank_intermediation_context":
            total = (
                len(bank_nim_credit_supply_context_rows)
                + len(bank_loan_repricing_context_rows)
                + len(tdcpass_borrower_rows)
                + len(fdic_margin_rows)
            )
            return (
                (
                    f"bank_nim_context_rows={len(bank_nim_credit_supply_context_rows)};"
                    f"bank_loan_repricing_context_rows={len(bank_loan_repricing_context_rows)};"
                    f"tdcpass_borrower_channel_rows={len(tdcpass_borrower_rows)};"
                    f"tdcpass_latest_quarter={tdcpass_latest_quarter};"
                    f"fdic_aggregate_retention_route_rows={len(fdic_margin_rows)};"
                    f"fdic_latest_quarter={fdic_latest_quarter};"
                    "promotion_gate_passed_rows=0"
                ),
                total,
                "pass_bank_intermediation_context_no_retention_distribution_bridge",
            )
        if source_family == "bank_behavior_current_demand_gate":
            total = (
                len(deposit_pricing_pass_through_rows)
                + len(tdc_rolling_pass_through_context_rows)
                + len(bank_nim_credit_supply_context_rows)
                + len(bank_loan_repricing_context_rows)
                + len(tdcpass_borrower_rows)
                + len(fdic_margin_rows)
            )
            return (
                (
                    f"bank_context_scanned_rows={total};"
                    f"tdcpass_borrower_channel_rows={len(tdcpass_borrower_rows)};"
                    f"fdic_aggregate_retention_route_rows={len(fdic_margin_rows)};"
                    "source_backed_iorb_specific_retention_distribution_timing_rows=0;"
                    f"bank_pass_review_blocked_after_proxy_rows={bank_pass_review_blocked}"
                ),
                total,
                "blocked_no_bank_retention_distribution_or_current_demand_timing_rows",
            )
        return (
            "source_family_not_matched_to_specific_scan",
            0,
            "blocked_unmatched_source_family",
        )

    rows: list[dict[str, str]] = []

    def add_attempt(
        *,
        row_id: str,
        attempt_family: str,
        contract_row: dict[str, str],
        contract_row_id_field: str,
        scan_result: str,
        source_row_count: int,
        source_backed_context_status: str,
    ) -> None:
        rows.append(
            {
                "final_recipient_current_demand_bridge_attempt_row_id": (
                    f"final_recipient_current_demand_bridge_attempt::{row_id}"
                ),
                "ratio_object_id": contract_row.get("ratio_object_id", ""),
                "component_id": contract_row.get("component_id", ""),
                "attempt_family": attempt_family,
                "source_or_gate_family": contract_row.get("source_or_gate_family", ""),
                "linked_contract_row_id": contract_row.get(contract_row_id_field, ""),
                "candidate_source_artifacts": (
                    contract_row.get("source_acquisition_execution_artifacts")
                    or contract_row.get("current_public_basis_artifacts", "")
                ),
                "candidate_source_row_count": str(source_row_count),
                "source_backed_context_status": source_backed_context_status,
                "source_scan_result": scan_result,
                "source_backed_amount_or_proxy_status": (
                    contract_row.get("current_public_basis_value_status", "")
                    or contract_row.get("best_available_proxy_status", "")
                ),
                "required_unit_of_observation": contract_row.get(
                    "required_unit_of_observation", ""
                ),
                "required_schema_fields": contract_row.get("required_schema_fields", ""),
                "present_source_backed_fields": contract_row.get(
                    "source_backed_proxy_fields", ""
                ),
                "missing_source_backed_fields": contract_row.get(
                    "assumption_or_missing_fields_blocking_admission", ""
                ),
                "bridge_materialization_status": (
                    "blocked_no_admissible_source_backed_final_recipient_current_demand_bridge"
                ),
                "exact_next_required_field_set": contract_row.get(
                    "next_acquisition_required_fields", ""
                ),
                "minimal_admission_test": contract_row.get(
                    "minimal_admission_test", ""
                ),
                "current_contract_outcome": contract_row.get(
                    "current_contract_outcome", ""
                ),
                "allowed_statement_now": contract_row.get(
                    "allowed_statement_now", ""
                ),
                "blocked_statement_now": contract_row.get(
                    "blocked_statement_now", ""
                ),
                "allowed_use": "source_backed_bridge_attempt_blocker_and_next_field_queue",
                "blocked_use": (
                    "runtime_default;canonical_rw_y;Evidence_Mode;prior_narrowing;"
                    "holder_allocation;pricing;incidence;welfare;tax;mpc_claims"
                ),
                "exact_blocker": contract_row.get("exact_blocker", ""),
                "claim_boundary": claim_boundary,
                "source_status": (
                    "source_scan_completed_context_available_bridge_not_admitted"
                ),
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )

    for contract_row in sorted(
        forecast_treasury_recipient_current_demand_evidence_contract_rows,
        key=lambda row: int(row.get("contract_rank", "0") or "0"),
    ):
        scan_result, source_row_count, context_status = treasury_source_scan(
            contract_row.get("source_or_gate_family", "")
        )
        add_attempt(
            row_id=f"treasury::{contract_row.get('contract_rank', '0').zfill(2)}",
            attempt_family="treasury_final_recipient_current_demand",
            contract_row=contract_row,
            contract_row_id_field=(
                "forecast_treasury_recipient_current_demand_evidence_contract_row_id"
            ),
            scan_result=scan_result,
            source_row_count=source_row_count,
            source_backed_context_status=context_status,
        )

    for contract_row in sorted(
        forecast_bank_behavior_current_demand_evidence_contract_rows,
        key=lambda row: int(row.get("contract_rank", "0") or "0"),
    ):
        scan_result, source_row_count, context_status = bank_source_scan(
            contract_row.get("source_or_gate_family", "")
        )
        add_attempt(
            row_id=f"bank::{contract_row.get('contract_rank', '0').zfill(2)}",
            attempt_family="bank_retained_margin_current_demand",
            contract_row=contract_row,
            contract_row_id_field=(
                "forecast_bank_behavior_current_demand_evidence_contract_row_id"
            ),
            scan_result=scan_result,
            source_row_count=source_row_count,
            source_backed_context_status=context_status,
        )

    return rows


def bank_behavior_bridge_source_contract_queue_rows(
    *,
    final_recipient_current_demand_bridge_attempt_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "bank_behavior_bridge_source_contract_queue_not_admission"
    source_contracts = {
        "bank_behavior_current_demand_gate": {
            "rank": "1",
            "focus": "iorb_specific_retention_distribution_timing_and_nonadditivity_panel",
            "required": (
                "bank_or_depositor_level_panel_linking_iorb_reserve_income_"
                "retention_deposit_pass_through_distribution_route_current_"
                "demand_timing_nonadditivity"
            ),
            "design": (
                "Acquire or build a source-owned panel with IORB/reserve-income "
                "cashflow, retention/distribution route, depositor or borrower "
                "cashflow response, timing lag, and nonadditivity checks at a "
                "bank-quarter or depositor-account grain."
            ),
            "action": (
                "source_contract_first_no_bank_current_demand_gate_reopen_until_"
                "iorb_specific_retention_timing_panel_exists"
            ),
        },
        "bank_intermediation_context": {
            "rank": "2",
            "focus": "borrower_credit_supply_cashflow_response_timing_link",
            "required": (
                "bank_group_quarter_panel_linking_reserve_income_deposit_expense_"
                "retained_earnings_dividends_loan_growth_credit_tightening_"
                "borrower_cashflow_response_timing"
            ),
            "design": (
                "Use the existing TDC pass-through and FDIC aggregate retention "
                "context only to specify a source-owned bridge that separates "
                "credit-supply effects from direct current-demand support."
            ),
            "action": (
                "build_or_acquire_bank_group_quarter_credit_supply_cashflow_"
                "response_design_before_any_prior_narrowing"
            ),
        },
        "reserve_income_and_deposit_pricing_context": {
            "rank": "3",
            "focus": "depositor_product_pass_through_cash_use_timing_panel",
            "required": (
                "deposit_product_or_account_panel_linking_rate_pass_through_"
                "holder_sector_realized_yield_current_spending_or_cash_use_"
                "timing_lag"
            ),
            "design": (
                "Treat deposit-pricing and rolling pass-through rows as context; "
                "the needed contract must identify the recipient/account class "
                "and current-demand timing, not only the rate gap."
            ),
            "action": (
                "source_depositor_product_timing_panel_before_deposit_incidence_"
                "or_current_demand_use"
            ),
        },
        "gross_iorb_cashflow_basis": {
            "rank": "4",
            "focus": "reserve_income_cashflow_retention_distribution_route_panel",
            "required": (
                "bank_quarter_panel_linking_reserve_income_cashflow_retained_"
                "earnings_dividend_distribution_route_recipient_class_timing_lag"
            ),
            "design": (
                "Keep gross IORB cashflow as a basis input until a source-owned "
                "retention/distribution route distinguishes bank retained margin "
                "from depositor or borrower cashflow."
            ),
            "action": (
                "source_retention_distribution_route_before_cashflow_basis_can_"
                "become_current_demand_support"
            ),
        },
    }

    bank_rows = [
        row
        for row in final_recipient_current_demand_bridge_attempt_rows
        if row.get("attempt_family") == "bank_retained_margin_current_demand"
    ]
    rows: list[dict[str, str]] = []
    for bridge_row in sorted(
        bank_rows,
        key=lambda row: int(
            source_contracts.get(row.get("source_or_gate_family", ""), {}).get(
                "rank", "99"
            )
        ),
    ):
        contract = source_contracts.get(bridge_row.get("source_or_gate_family", ""))
        if not contract:
            continue
        rows.append(
            {
                "bank_behavior_bridge_source_contract_queue_row_id": (
                    "bank_behavior_bridge_source_contract_queue::"
                    f"{contract['rank'].zfill(2)}"
                ),
                "linked_bridge_attempt_row_id": bridge_row[
                    "final_recipient_current_demand_bridge_attempt_row_id"
                ],
                "queue_rank": contract["rank"],
                "source_contract_focus": contract["focus"],
                "source_or_gate_family": bridge_row["source_or_gate_family"],
                "candidate_source_artifacts": bridge_row["candidate_source_artifacts"],
                "candidate_source_row_count": bridge_row["candidate_source_row_count"],
                "source_scan_result": bridge_row["source_scan_result"],
                "available_context_status": bridge_row["source_backed_context_status"],
                "required_unit_of_observation": bridge_row[
                    "required_unit_of_observation"
                ],
                "required_schema_fields": bridge_row["required_schema_fields"],
                "present_source_backed_fields": bridge_row[
                    "present_source_backed_fields"
                ],
                "missing_source_backed_fields": bridge_row[
                    "missing_source_backed_fields"
                ],
                "exact_next_required_field_set": bridge_row[
                    "exact_next_required_field_set"
                ],
                "required_new_source_contract": contract["required"],
                "source_acquisition_design": contract["design"],
                "minimal_admission_test": bridge_row["minimal_admission_test"],
                "blocking_status": (
                    "blocked_bank_behavior_source_contract_missing_required_fields"
                ),
                "promotion_decision_status": (
                    "blocked_no_bank_current_demand_or_denominator_promotion"
                ),
                "next_backend_action": contract["action"],
                "allowed_use": "bank_behavior_source_contract_queue_only",
                "blocked_use": (
                    "runtime_default;canonical_rw_y;Evidence_Mode;prior_narrowing;"
                    "holder_allocation;pricing;incidence;welfare;tax;mpc_claims"
                ),
                "claim_boundary": claim_boundary,
                "source_status": "source_contract_queue_context_only_not_admission",
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )
    return rows


