def forecast_path_ratio_driver_ranking_rows(
    *,
    forecast_path_ratio_sensitivity_summary_rows: Sequence[dict[str, str]],
    forecast_path_ratio_scenario_registry_rows: Sequence[dict[str, str]],
    forecast_path_ratio_scenario_frontier_rows: Sequence[dict[str, str]],
    forecast_path_ratio_interpretation_rows: Sequence[dict[str, str]],
    forecast_path_ratio_recipient_leakage_rows: Sequence[dict[str, str]],
    forecast_path_ratio_source_specific_interpretation_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "forecast_path_ratio_driver_ranking_noncanonical"
    registry_by_id = {
        row["forecast_path_ratio_scenario_registry_row_id"]: row
        for row in forecast_path_ratio_scenario_registry_rows
    }
    frontier_by_registry_id = {
        row["forecast_path_ratio_scenario_registry_row_id"]: row
        for row in forecast_path_ratio_scenario_frontier_rows
    }
    frontier_top1_by_year = {
        row["forecast_year"]: row
        for row in forecast_path_ratio_scenario_frontier_rows
        if row["frontier_rank_within_year"] == "1"
    }
    interpretation_by_handle = {
        (
            row["forecast_path_ratio_scenario_registry_row_id"],
            row["component_id"],
        ): row
        for row in forecast_path_ratio_interpretation_rows
    }
    recipient_leakage_by_interpretation_id = {
        row["forecast_path_ratio_interpretation_row_id"]: row
        for row in forecast_path_ratio_recipient_leakage_rows
    }
    source_specific_by_interpretation_id = {
        row["forecast_path_ratio_interpretation_row_id"]: row
        for row in forecast_path_ratio_source_specific_interpretation_rows
    }
    rows: list[dict[str, str]] = []
    rows_by_year: dict[str, list[dict[str, str]]] = defaultdict(list)
    for sensitivity_row in forecast_path_ratio_sensitivity_summary_rows:
        year = sensitivity_row["forecast_year"]
        matched_row = registry_by_id[sensitivity_row["matched_scenario_registry_row_id"]]
        frontier_row = frontier_top1_by_year[year]
        matched_frontier_row = frontier_by_registry_id[
            matched_row["forecast_path_ratio_scenario_registry_row_id"]
        ]
        matched_interpretation_row = interpretation_by_handle[
            (
                matched_row["forecast_path_ratio_scenario_registry_row_id"],
                matched_frontier_row["dominant_direct_component_id"],
            )
        ]
        matched_recipient_leakage_row = recipient_leakage_by_interpretation_id[
            matched_interpretation_row["forecast_path_ratio_interpretation_row_id"]
        ]
        matched_source_specific_row = source_specific_by_interpretation_id[
            matched_interpretation_row["forecast_path_ratio_interpretation_row_id"]
        ]
        frontier_interpretation_row = interpretation_by_handle[
            (
                frontier_row["forecast_path_ratio_scenario_registry_row_id"],
                frontier_row["dominant_direct_component_id"],
            )
        ]
        frontier_recipient_leakage_row = recipient_leakage_by_interpretation_id[
            frontier_interpretation_row["forecast_path_ratio_interpretation_row_id"]
        ]
        frontier_source_specific_row = source_specific_by_interpretation_id[
            frontier_interpretation_row["forecast_path_ratio_interpretation_row_id"]
        ]
        delta_numerator = _decimal_or_zero(
            sensitivity_row["delta_numerator_bil_vs_reference"]
        )
        delta_denominator = _decimal_or_zero(
            sensitivity_row["delta_denominator_bil_vs_reference"]
        )
        delta_gap = _decimal_or_zero(
            sensitivity_row["delta_remaining_gap_bil_vs_reference"]
        )
        reference_row = registry_by_id[sensitivity_row["reference_scenario_registry_row_id"]]
        if delta_numerator == 0 and delta_denominator == 0:
            driver_channel_classification = "reference_no_material_delta"
            scenario_axis_channel_classification = "non_profile_axis"
        elif sensitivity_row["scenario_axis"] == "channel_conversion_profile_id":
            driver_channel_classification = _forecast_profile_delta_channel_classification(
                reference_row,
                matched_row,
            )
            scenario_axis_channel_classification = (
                "channel_specific_current_demand_conversion_profile"
            )
        elif delta_numerator != 0 and delta_denominator == 0:
            driver_channel_classification = "numerator_only_driver"
            scenario_axis_channel_classification = "non_profile_axis"
        elif delta_numerator == 0 and delta_denominator != 0:
            driver_channel_classification = "denominator_only_driver"
            scenario_axis_channel_classification = "non_profile_axis"
        elif delta_numerator != 0 and delta_denominator != 0:
            driver_channel_classification = "mixed_numerator_and_denominator_driver"
            scenario_axis_channel_classification = "non_profile_axis"
        else:
            driver_channel_classification = "reference_no_material_delta"
            scenario_axis_channel_classification = "non_profile_axis"
        if delta_gap < 0:
            driver_effect_classification = "moves_closer_to_wall"
        elif delta_gap > 0:
            driver_effect_classification = "moves_further_from_wall"
        else:
            driver_effect_classification = "reference_no_change"
        row = {
            "forecast_path_ratio_driver_ranking_row_id": (
                "forecast_path_ratio_driver_ranking::"
                f"{year}::{sensitivity_row['scenario_axis']}::"
                f"{matched_row[sensitivity_row['scenario_axis']]}"
            ),
            "ratio_object_id": "rw_forecast_wall_ratio_path",
            "forecast_year": year,
            "scenario_axis": sensitivity_row["scenario_axis"],
            "scenario_axis_role": sensitivity_row["scenario_axis_role"],
            "scenario_axis_setting": matched_row[sensitivity_row["scenario_axis"]],
            "scenario_axis_value": sensitivity_row["scenario_axis_value"],
            "scenario_axis_channel_classification": (
                scenario_axis_channel_classification
            ),
            "reference_scenario_registry_row_id": sensitivity_row[
                "reference_scenario_registry_row_id"
            ],
            "matched_scenario_registry_row_id": sensitivity_row[
                "matched_scenario_registry_row_id"
            ],
            "frontier_scenario_registry_row_id": frontier_row[
                "forecast_path_ratio_scenario_registry_row_id"
            ],
            "matched_dominant_direct_component_id": matched_frontier_row[
                "dominant_direct_component_id"
            ],
            "frontier_dominant_direct_component_id": frontier_row[
                "dominant_direct_component_id"
            ],
            "matched_forecast_path_ratio_interpretation_row_id": (
                matched_interpretation_row[
                    "forecast_path_ratio_interpretation_row_id"
                ]
            ),
            "frontier_forecast_path_ratio_interpretation_row_id": (
                frontier_interpretation_row[
                    "forecast_path_ratio_interpretation_row_id"
                ]
            ),
            "matched_source_backed_context_status": matched_interpretation_row[
                "source_backed_context_status"
            ],
            "frontier_source_backed_context_status": frontier_interpretation_row[
                "source_backed_context_status"
            ],
            "matched_assumption_conversion_status": matched_interpretation_row[
                "assumption_conversion_status"
            ],
            "frontier_assumption_conversion_status": (
                frontier_interpretation_row["assumption_conversion_status"]
            ),
            "matched_interpretation_boundary_status": matched_interpretation_row[
                "interpretation_boundary_status"
            ],
            "frontier_interpretation_boundary_status": (
                frontier_interpretation_row["interpretation_boundary_status"]
            ),
            "matched_forecast_path_ratio_recipient_leakage_row_id": (
                matched_recipient_leakage_row[
                    "forecast_path_ratio_recipient_leakage_row_id"
                ]
            ),
            "frontier_forecast_path_ratio_recipient_leakage_row_id": (
                frontier_recipient_leakage_row[
                    "forecast_path_ratio_recipient_leakage_row_id"
                ]
            ),
            "matched_forecast_path_ratio_source_specific_interpretation_row_id": (
                matched_source_specific_row[
                    "forecast_path_ratio_source_specific_interpretation_row_id"
                ]
            ),
            "frontier_forecast_path_ratio_source_specific_interpretation_row_id": (
                frontier_source_specific_row[
                    "forecast_path_ratio_source_specific_interpretation_row_id"
                ]
            ),
            "matched_forecast_recipient_leakage_status": (
                matched_recipient_leakage_row["forecast_recipient_leakage_status"]
            ),
            "frontier_forecast_recipient_leakage_status": (
                frontier_recipient_leakage_row["forecast_recipient_leakage_status"]
            ),
            "matched_source_specific_tightening_status": (
                matched_source_specific_row[
                    "source_specific_interpretation_tightening_status"
                ]
            ),
            "frontier_source_specific_tightening_status": (
                frontier_source_specific_row[
                    "source_specific_interpretation_tightening_status"
                ]
            ),
            "matched_prior_narrowing_decision": (
                matched_recipient_leakage_row["prior_narrowing_decision"]
            ),
            "frontier_prior_narrowing_decision": (
                frontier_recipient_leakage_row["prior_narrowing_decision"]
            ),
            "driver_effect_classification": driver_effect_classification,
            "driver_channel_classification": driver_channel_classification,
            "frontier_axis_alignment_status": (
                "frontier_uses_driver_setting"
                if matched_row[sensitivity_row["scenario_axis"]]
                == frontier_row[sensitivity_row["scenario_axis"]]
                else "frontier_uses_different_setting"
            ),
            "delta_ratio_vs_reference": sensitivity_row["delta_ratio_vs_reference"],
            "delta_numerator_bil_vs_reference": sensitivity_row[
                "delta_numerator_bil_vs_reference"
            ],
            "delta_denominator_bil_vs_reference": sensitivity_row[
                "delta_denominator_bil_vs_reference"
            ],
            "delta_remaining_gap_bil_vs_reference": sensitivity_row[
                "delta_remaining_gap_bil_vs_reference"
            ],
            "closeness_improvement_bil": _format_decimal(
                max(-delta_gap, Decimal("0"))
            ),
            "closeness_setback_bil": _format_decimal(max(delta_gap, Decimal("0"))),
            "absolute_ratio_delta_rank_within_year": sensitivity_row[
                "absolute_ratio_delta_rank_within_year"
            ],
            "closeness_improvement_rank_within_year": "",
            "allowed_use": "forecast_path_ratio_driver_ranking",
            "blocked_use": "runtime_default;canonical_rw_y",
            "exact_blocker": "",
            "claim_boundary": claim_boundary,
            "source_status": sensitivity_row["source_status"],
            "canonical_ratio_entry": "false",
            **disabled,
        }
        rows.append(row)
        rows_by_year[year].append(row)
    for year, year_rows in rows_by_year.items():
        ranked = sorted(
            year_rows,
            key=lambda row: (
                _decimal_or_zero(row["closeness_improvement_bil"]),
                abs(_decimal_or_zero(row["delta_ratio_vs_reference"])),
            ),
            reverse=True,
        )
        for rank, row in enumerate(ranked, start=1):
            row["closeness_improvement_rank_within_year"] = str(rank)
    return rows


def forecast_path_ratio_driver_dominance_rows(
    *,
    forecast_path_ratio_driver_ranking_rows: Sequence[dict[str, str]],
    forecast_path_ratio_scenario_registry_rows: Sequence[dict[str, str]],
    forecast_path_ratio_scenario_frontier_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "forecast_path_ratio_driver_dominance_noncanonical"
    registry_by_id = {
        row["forecast_path_ratio_scenario_registry_row_id"]: row
        for row in forecast_path_ratio_scenario_registry_rows
    }
    frontier_top1_by_year = {
        row["forecast_year"]: row
        for row in forecast_path_ratio_scenario_frontier_rows
        if row["frontier_rank_within_year"] == "1"
    }
    rows_by_year: dict[str, list[dict[str, str]]] = defaultdict(list)
    for row in forecast_path_ratio_driver_ranking_rows:
        rows_by_year[row["forecast_year"]].append(row)

    rows: list[dict[str, str]] = []
    for year in sorted(rows_by_year):
        year_rows = rows_by_year[year]
        dominant_row = max(
            year_rows,
            key=lambda row: (
                _decimal_or_zero(row["closeness_improvement_bil"]),
                abs(_decimal_or_zero(row["delta_ratio_vs_reference"])),
            ),
        )
        reference_row = registry_by_id[dominant_row["reference_scenario_registry_row_id"]]
        frontier_row = frontier_top1_by_year[year]
        rows.append(
            {
                "forecast_path_ratio_driver_dominance_row_id": (
                    "forecast_path_ratio_driver_dominance::"
                    f"{year}::{dominant_row['scenario_axis']}"
                ),
                "ratio_object_id": "rw_forecast_wall_ratio_path",
                "forecast_year": year,
                "reference_scenario_registry_row_id": dominant_row[
                    "reference_scenario_registry_row_id"
                ],
                "frontier_scenario_registry_row_id": frontier_row[
                    "forecast_path_ratio_scenario_registry_row_id"
                ],
                "dominant_driver_ranking_row_id": dominant_row[
                    "forecast_path_ratio_driver_ranking_row_id"
                ],
                "dominant_driver_axis": dominant_row["scenario_axis"],
                "dominant_driver_axis_role": dominant_row["scenario_axis_role"],
                "dominant_driver_setting": dominant_row["scenario_axis_setting"],
                "dominant_driver_value": dominant_row["scenario_axis_value"],
                "dominant_driver_axis_channel_classification": dominant_row[
                    "scenario_axis_channel_classification"
                ],
                "dominant_row_matched_interpretation_row_id": dominant_row[
                    "matched_forecast_path_ratio_interpretation_row_id"
                ],
                "frontier_rank1_interpretation_row_id": dominant_row[
                    "frontier_forecast_path_ratio_interpretation_row_id"
                ],
                "dominant_row_matched_interpretation_boundary_status": dominant_row[
                    "matched_interpretation_boundary_status"
                ],
                "frontier_rank1_interpretation_boundary_status": dominant_row[
                    "frontier_interpretation_boundary_status"
                ],
                "dominant_driver_effect_classification": dominant_row[
                    "driver_effect_classification"
                ],
                "dominant_driver_channel_classification": dominant_row[
                    "driver_channel_classification"
                ],
                "frontier_uses_dominant_driver_setting": (
                    "true"
                    if dominant_row["frontier_axis_alignment_status"]
                    == "frontier_uses_driver_setting"
                    else "false"
                ),
                "dominant_driver_ratio_delta_vs_reference": dominant_row[
                    "delta_ratio_vs_reference"
                ],
                "dominant_driver_numerator_delta_vs_reference": dominant_row[
                    "delta_numerator_bil_vs_reference"
                ],
                "dominant_driver_denominator_delta_vs_reference": dominant_row[
                    "delta_denominator_bil_vs_reference"
                ],
                "dominant_driver_closeness_improvement_bil": dominant_row[
                    "closeness_improvement_bil"
                ],
                "dominant_driver_closeness_setback_bil": dominant_row[
                    "closeness_setback_bil"
                ],
                "frontier_rank1_ratio": frontier_row["forecast_incremental_path_ratio"],
                "frontier_rank1_remaining_gap_bil": frontier_row[
                    "remaining_gap_to_wall_bil"
                ],
                "frontier_rank1_dominant_direct_component_id": frontier_row[
                    "dominant_direct_component_id"
                ],
                "reference_ratio": reference_row["forecast_incremental_path_ratio"],
                "reference_remaining_gap_bil": reference_row[
                    "remaining_gap_to_wall_bil"
                ],
                "allowed_use": "forecast_path_ratio_driver_dominance_summary",
                "blocked_use": "runtime_default;canonical_rw_y",
                "exact_blocker": "",
                "claim_boundary": claim_boundary,
                "source_status": dominant_row["source_status"],
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )
    return rows


def forecast_path_ratio_consumer_ladder_rows(
    *,
    forecast_path_ratio_scenario_registry_rows: Sequence[dict[str, str]],
    forecast_path_ratio_scenario_frontier_rows: Sequence[dict[str, str]],
    forecast_path_ratio_interpretation_rows: Sequence[dict[str, str]],
    forecast_path_ratio_driver_dominance_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "forecast_path_ratio_consumer_ladder_noncanonical"
    frontier_by_registry_id = {
        row["forecast_path_ratio_scenario_registry_row_id"]: row
        for row in forecast_path_ratio_scenario_frontier_rows
    }
    top_frontier_rows_by_year: dict[str, list[dict[str, str]]] = defaultdict(list)
    for row in forecast_path_ratio_scenario_frontier_rows:
        if int(row["frontier_rank_within_year"]) <= 3:
            top_frontier_rows_by_year[row["forecast_year"]].append(row)
    dominance_by_year = {
        row["forecast_year"]: row for row in forecast_path_ratio_driver_dominance_rows
    }
    interpretation_by_handle = {
        (
            row["forecast_path_ratio_scenario_registry_row_id"],
            row["component_id"],
        ): row
        for row in forecast_path_ratio_interpretation_rows
    }
    registry_by_year: dict[str, list[dict[str, str]]] = defaultdict(list)
    for row in forecast_path_ratio_scenario_registry_rows:
        registry_by_year[row["forecast_year"]].append(row)

    role_specs = [
        ("closest_to_wall_top1", 1),
        ("closest_to_wall_top2", 2),
        ("closest_to_wall_top3", 3),
        ("reference_scenario", 4),
    ]
    rows: list[dict[str, str]] = []
    for year in sorted(registry_by_year):
        year_registry_rows = registry_by_year[year]
        reference_registry_row = min(
            year_registry_rows,
            key=lambda row: _forecast_reference_priority(
                {
                    "mpc_scenario": row["mpc_scenario"],
                    "maturity_scenario": row["maturity_scenario"],
                    "holder_scenario": row["holder_scenario"],
                }
            ),
        )
        top_rows = {
            f"closest_to_wall_top{index}": row
            for index, row in enumerate(
                sorted(
                    top_frontier_rows_by_year[year],
                    key=lambda row: int(row["frontier_rank_within_year"]),
                ),
                start=1,
            )
        }
        selected_rows = {
            **top_rows,
            "reference_scenario": frontier_by_registry_id[
                reference_registry_row["forecast_path_ratio_scenario_registry_row_id"]
            ],
        }
        dominance_row = dominance_by_year[year]
        for role, order in role_specs:
            frontier_row = selected_rows[role]
            dominant_component_id = frontier_row["dominant_direct_component_id"]
            interpretation_row = interpretation_by_handle[
                (
                    frontier_row["forecast_path_ratio_scenario_registry_row_id"],
                    dominant_component_id,
                )
            ]
            registry_row = next(
                row
                for row in year_registry_rows
                if row["forecast_path_ratio_scenario_registry_row_id"]
                == frontier_row["forecast_path_ratio_scenario_registry_row_id"]
            )
            rows.append(
                {
                    "forecast_path_ratio_consumer_ladder_row_id": (
                        "forecast_path_ratio_consumer_ladder::"
                        f"{year}::{order:02d}::{role}"
                    ),
                    "ratio_object_id": "rw_forecast_wall_ratio_path",
                    "forecast_year": year,
                    "ladder_entry_role": role,
                    "ladder_entry_order_within_year": str(order),
                    "forecast_path_ratio_scenario_registry_row_id": registry_row[
                        "forecast_path_ratio_scenario_registry_row_id"
                    ],
                    "forecast_path_ratio_scenario_frontier_row_id": frontier_row[
                        "forecast_path_ratio_scenario_frontier_row_id"
                    ],
                    "linked_driver_dominance_row_id": dominance_row[
                        "forecast_path_ratio_driver_dominance_row_id"
                    ],
                    "linked_forecast_path_ratio_interpretation_row_id": (
                        interpretation_row["forecast_path_ratio_interpretation_row_id"]
                    ),
                    "forecast_scenario_id": registry_row["forecast_scenario_id"],
                    "channel_conversion_profile_id": registry_row[
                        "channel_conversion_profile_id"
                    ],
                    "mpc_scenario": registry_row["mpc_scenario"],
                    "maturity_scenario": registry_row["maturity_scenario"],
                    "holder_scenario": registry_row["holder_scenario"],
                    "forecast_incremental_path_ratio": registry_row[
                        "forecast_incremental_path_ratio"
                    ],
                    "remaining_gap_to_wall_bil": registry_row[
                        "remaining_gap_to_wall_bil"
                    ],
                    "numerator_total_bil": registry_row["numerator_total_bil"],
                    "denominator_bil": registry_row["denominator_bil"],
                    "dominant_direct_component_id": dominant_component_id,
                    "source_backed_context_status": interpretation_row[
                        "source_backed_context_status"
                    ],
                    "assumption_conversion_status": interpretation_row[
                        "assumption_conversion_status"
                    ],
                    "interpretation_boundary_status": interpretation_row[
                        "interpretation_boundary_status"
                    ],
                    "deposit_pass_through_materialization_status": (
                        interpretation_row[
                            "deposit_pass_through_materialization_status"
                        ]
                    ),
                    "row_reportability_status": registry_row[
                        "row_reportability_status"
                    ],
                    "allowed_use": "forecast_path_ratio_consumer_ladder",
                    "blocked_use": "runtime_default;canonical_rw_y",
                    "exact_blocker": interpretation_row["exact_blocker"],
                    "claim_boundary": claim_boundary,
                    "source_status": registry_row["source_status"],
                    "canonical_ratio_entry": "false",
                    **disabled,
                }
            )
    return rows


