def forecast_assumption_calibration_registry_rows(
    *,
    forecast_channel_conversion_profile_registry_rows: Sequence[dict[str, str]],
    forecast_path_ratio_pass_through_scenario_axis_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "forecast_assumption_calibration_registry_noncanonical"
    rows: list[dict[str, str]] = []
    parameter_specs = [
        (
            "treasury_interest_current_demand_conversion",
            "treasury_recipient_current_demand_share",
            "treasury_recipient_current_demand_share",
        ),
        (
            "tdc_deposit_balance_current_demand_conversion",
            "tdc_deposit_balance_current_demand_conversion_assumption",
            "tdc_deposit_balance_current_demand_conversion_assumption",
        ),
        (
            "bank_margin_direct_demand_conversion",
            "bank_retained_margin_direct_demand_share",
            "bank_retained_margin_direct_demand_share",
        ),
    ]
    for profile_row in forecast_channel_conversion_profile_registry_rows:
        for rank, (family, name, value_field) in enumerate(parameter_specs, start=1):
            rows.append(
                {
                    "forecast_assumption_calibration_row_id": (
                        "forecast_assumption_calibration::"
                        f"{profile_row['channel_conversion_profile_id']}::{name}"
                    ),
                    "ratio_object_id": "rw_forecast_wall_ratio_path",
                    "channel_conversion_profile_id": profile_row[
                        "channel_conversion_profile_id"
                    ],
                    "legacy_mpc_scenario_alias": profile_row[
                        "legacy_mpc_scenario_alias"
                    ],
                    "parameter_family": family,
                    "parameter_name": name,
                    "parameter_role": "assumption_mode_profile_parameter",
                    "parameter_value": profile_row[value_field],
                    "parameter_rank_within_family": str(rank),
                    "evidence_class": profile_row["evidence_class"],
                    "admission_status": profile_row["admission_status"],
                    "blocked_claims": profile_row["blocked_claims"],
                    "allowed_use": "forecast_assumption_calibration_registry",
                    "blocked_use": "runtime_default;canonical_rw_y",
                    "exact_blocker": "profile_values_are_noncanonical_assumption_mode_only",
                    "claim_boundary": claim_boundary,
                    "source_status": profile_row["source_status"],
                    "canonical_ratio_entry": "false",
                    **disabled,
                }
            )
    for rank, pass_row in enumerate(
        sorted(
            forecast_path_ratio_pass_through_scenario_axis_rows,
            key=lambda row: _forecast_pass_through_priority(row),
        ),
        start=1,
    ):
        rows.append(
            {
                "forecast_assumption_calibration_row_id": (
                    "forecast_assumption_calibration::pass_through::"
                    f"{pass_row['pass_through_scenario']}"
                ),
                "ratio_object_id": "rw_forecast_wall_ratio_path",
                "channel_conversion_profile_id": "",
                "legacy_mpc_scenario_alias": "",
                "parameter_family": "deposit_pass_through_beta",
                "parameter_name": "deposit_pass_through_beta",
                "parameter_role": pass_row["pass_through_scenario_role"],
                "parameter_value": pass_row["pass_through_beta"],
                "parameter_rank_within_family": str(rank),
                "evidence_class": "source_informed_scenario_family",
                "admission_status": "scenario_only_noncanonical",
                "blocked_claims": (
                    "automatic_runtime_selector;recipient_current_demand_proof;"
                    "canonical_rw_y"
                ),
                "allowed_use": "forecast_assumption_calibration_registry",
                "blocked_use": (
                    "runtime_default;canonical_rw_y;automatic_pass_through_runtime_selector"
                ),
                "exact_blocker": "pass_through_is_scenario_only_not_runtime_default",
                "claim_boundary": claim_boundary,
                "source_status": pass_row["source_status"],
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )
    return rows


