def forecast_scenario_product_summary_rows(
    *,
    forecast_path_ratio_scenario_registry_rows: Sequence[dict[str, str]],
    forecast_path_ratio_scenario_frontier_rows: Sequence[dict[str, str]],
    forecast_path_ratio_driver_dominance_rows: Sequence[dict[str, str]],
    forecast_channel_conversion_profile_registry_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "forecast_scenario_product_summary_noncanonical"
    profile_by_id = {
        row["channel_conversion_profile_id"]: row
        for row in forecast_channel_conversion_profile_registry_rows
    }
    frontier_by_registry_id = {
        row["forecast_path_ratio_scenario_registry_row_id"]: row
        for row in forecast_path_ratio_scenario_frontier_rows
    }
    dominance_by_year = {
        row["forecast_year"]: row for row in forecast_path_ratio_driver_dominance_rows
    }
    rows_by_year_profile: dict[tuple[str, str], list[dict[str, str]]] = defaultdict(list)
    for row in forecast_path_ratio_scenario_registry_rows:
        rows_by_year_profile[
            (row["forecast_year"], row["channel_conversion_profile_id"])
        ].append(row)
    rows: list[dict[str, str]] = []
    for forecast_year, profile_id in sorted(rows_by_year_profile):
        scenario_rows = rows_by_year_profile[(forecast_year, profile_id)]
        best_row = max(
            scenario_rows,
            key=lambda row: (
                _decimal_or_zero(row["forecast_incremental_path_ratio"]),
                -_decimal_or_zero(row["remaining_gap_to_wall_bil"]),
                _forecast_reference_priority(row),
            ),
        )
        profile_row = profile_by_id[profile_id]
        frontier_row = frontier_by_registry_id[
            best_row["forecast_path_ratio_scenario_registry_row_id"]
        ]
        dominance_row = dominance_by_year[forecast_year]
        ratio = _decimal_or_zero(best_row["forecast_incremental_path_ratio"])
        if ratio >= Decimal("1"):
            wall_case_classification = "wall_hit"
        elif ratio >= Decimal("0.5"):
            wall_case_classification = "near_wall"
        else:
            wall_case_classification = "mostly_tightening"
        rows.append(
            {
                "forecast_scenario_product_summary_row_id": (
                    "forecast_scenario_product_summary::"
                    f"{forecast_year}::{profile_id}"
                ),
                "ratio_object_id": "rw_forecast_wall_ratio_path",
                "forecast_year": forecast_year,
                "channel_conversion_profile_id": profile_id,
                "legacy_mpc_scenario_alias": profile_row["legacy_mpc_scenario_alias"],
                "best_forecast_path_ratio_scenario_registry_row_id": best_row[
                    "forecast_path_ratio_scenario_registry_row_id"
                ],
                "best_forecast_path_ratio_scenario_frontier_row_id": frontier_row[
                    "forecast_path_ratio_scenario_frontier_row_id"
                ],
                "linked_driver_dominance_row_id": dominance_row[
                    "forecast_path_ratio_driver_dominance_row_id"
                ],
                "best_maturity_scenario": best_row["maturity_scenario"],
                "best_holder_scenario": best_row["holder_scenario"],
                "treasury_recipient_current_demand_share": best_row[
                    "treasury_recipient_current_demand_share"
                ],
                "tdc_ex_overlap_current_demand_share": best_row[
                    "tdc_ex_overlap_current_demand_share"
                ],
                "tdc_deposit_balance_current_demand_conversion_assumption": best_row[
                    "tdc_deposit_balance_current_demand_conversion_assumption"
                ],
                "bank_retained_margin_direct_demand_share": best_row[
                    "bank_retained_margin_direct_demand_share"
                ],
                "best_forecast_incremental_path_ratio": best_row[
                    "forecast_incremental_path_ratio"
                ],
                "best_remaining_gap_to_wall_bil": best_row[
                    "remaining_gap_to_wall_bil"
                ],
                "wall_case_classification": wall_case_classification,
                "dominant_direct_component_id": frontier_row[
                    "dominant_direct_component_id"
                ],
                "dominant_assumption_axis": dominance_row["dominant_driver_axis"],
                "dominant_assumption_axis_channel_classification": dominance_row[
                    "dominant_driver_axis_channel_classification"
                ],
                "dominant_driver_effect_classification": dominance_row[
                    "dominant_driver_effect_classification"
                ],
                "blocked_claims": profile_row["blocked_claims"],
                "allowed_use": "forecast_scenario_product_summary",
                "blocked_use": "runtime_default;canonical_rw_y",
                "exact_blocker": "product_summary_is_noncanonical_assumption_mode_only",
                "claim_boundary": claim_boundary,
                "source_status": best_row["source_status"],
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )
    return rows


