def forecast_treasury_recipient_calibration_comparison_rows(
    *,
    forecast_path_ratio_scenario_registry_rows: Sequence[dict[str, str]],
    forecast_path_ratio_decomposition_rows: Sequence[dict[str, str]],
    forecast_treasury_recipient_calibration_registry_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = (
        "forecast_treasury_recipient_calibration_comparison_noncanonical"
    )
    decomposition_by_bundle_component = {
        (
            row["forecast_path_ratio_scenario_registry_row_id"],
            row["component_id"],
        ): row
        for row in forecast_path_ratio_decomposition_rows
    }
    calibration_by_id = {
        row["treasury_calibration_id"]: row
        for row in forecast_treasury_recipient_calibration_registry_rows
    }
    rows: list[dict[str, str]] = []
    for scenario_row in forecast_path_ratio_scenario_registry_rows:
        treasury_row = decomposition_by_bundle_component[
            (
                scenario_row["forecast_path_ratio_scenario_registry_row_id"],
                "domestic_nonbank_interest_support",
            )
        ]
        base_treasury_support = _decimal_or_zero(treasury_row["component_value_bil"])
        base_numerator_total = _decimal_or_zero(scenario_row["numerator_total_bil"])
        denominator = _decimal_or_zero(scenario_row["denominator_bil"])
        base_share = _decimal_or_zero(
            scenario_row["treasury_recipient_current_demand_share"]
        )
        for calibration_id in ("low", "base", "high"):
            calibration_row = calibration_by_id[calibration_id]
            multiplier = _decimal_or_zero(
                calibration_row["treasury_support_multiplier_vs_bridge_reference"]
            )
            adjusted_treasury_support = base_treasury_support * multiplier
            adjusted_numerator_total = (
                base_numerator_total - base_treasury_support + adjusted_treasury_support
            )
            adjusted_ratio = (
                Decimal("0")
                if denominator == 0
                else adjusted_numerator_total / denominator
            )
            adjusted_gap = max(Decimal("0"), denominator - adjusted_numerator_total)
            effective_share = base_share * multiplier
            rows.append(
                {
                    "forecast_treasury_recipient_calibration_comparison_row_id": (
                        "forecast_treasury_recipient_calibration_comparison::"
                        f"{scenario_row['forecast_scenario_id']}::{calibration_id}"
                    ),
                    "ratio_object_id": "rw_forecast_wall_ratio_path",
                    "forecast_year": scenario_row["forecast_year"],
                    "forecast_scenario_id": scenario_row["forecast_scenario_id"],
                    "forecast_path_ratio_scenario_registry_row_id": scenario_row[
                        "forecast_path_ratio_scenario_registry_row_id"
                    ],
                    "forecast_path_ratio_decomposition_row_id": treasury_row[
                        "forecast_path_ratio_decomposition_row_id"
                    ],
                    "linked_forecast_treasury_recipient_calibration_row_id": (
                        calibration_row[
                            "forecast_treasury_recipient_calibration_row_id"
                        ]
                    ),
                    "linked_bridge_pass_review_row_id": calibration_row[
                        "linked_bridge_pass_review_row_id"
                    ],
                    "channel_conversion_profile_id": scenario_row[
                        "channel_conversion_profile_id"
                    ],
                    "legacy_mpc_scenario_alias": scenario_row[
                        "legacy_mpc_scenario_alias"
                    ],
                    "mpc_scenario": scenario_row["mpc_scenario"],
                    "maturity_scenario": scenario_row["maturity_scenario"],
                    "holder_scenario": scenario_row["holder_scenario"],
                    "treasury_calibration_id": calibration_id,
                    "treasury_calibration_band": calibration_row[
                        "treasury_calibration_band"
                    ],
                    "treasury_support_multiplier_vs_bridge_reference": calibration_row[
                        "treasury_support_multiplier_vs_bridge_reference"
                    ],
                    "base_treasury_recipient_current_demand_share": scenario_row[
                        "treasury_recipient_current_demand_share"
                    ],
                    "effective_treasury_recipient_current_demand_share": _format_decimal(
                        effective_share
                    ),
                    "base_treasury_support_bil": treasury_row["component_value_bil"],
                    "adjusted_treasury_support_bil": _format_decimal(
                        adjusted_treasury_support
                    ),
                    "delta_treasury_support_bil": _format_decimal(
                        adjusted_treasury_support - base_treasury_support
                    ),
                    "base_numerator_total_bil": scenario_row["numerator_total_bil"],
                    "adjusted_numerator_total_bil": _format_decimal(
                        adjusted_numerator_total
                    ),
                    "denominator_bil": scenario_row["denominator_bil"],
                    "adjusted_forecast_incremental_path_ratio": _format_decimal(
                        adjusted_ratio
                    ),
                    "adjusted_remaining_gap_to_wall_bil": _format_decimal(
                        adjusted_gap
                    ),
                    "wall_case_classification": _wall_case_classification_from_ratio(
                        adjusted_ratio
                    ),
                    "treasury_calibration_effect_classification": "",
                    "dominant_direct_component_id": scenario_row[
                        "dominant_direct_component_id"
                    ]
                    if "dominant_direct_component_id" in scenario_row
                    else "domestic_nonbank_interest_support",
                    "blocked_claims": calibration_row["blocked_claims"],
                    "allowed_use": "forecast_treasury_recipient_calibration_comparison",
                    "blocked_use": "runtime_default;canonical_rw_y",
                    "exact_blocker": (
                        "treasury_recipient_calibration_overlay_is_noncanonical"
                    ),
                    "claim_boundary": claim_boundary,
                    "source_status": (
                        f"{scenario_row['source_status']};"
                        f"{calibration_row['source_status']}"
                    ),
                    "canonical_ratio_entry": "false",
                    **disabled,
                }
            )
    rows_by_scenario: dict[str, dict[str, dict[str, str]]] = defaultdict(dict)
    for row in rows:
        rows_by_scenario[row["forecast_scenario_id"]][row["treasury_calibration_id"]] = row
    for scenario_rows in rows_by_scenario.values():
        base_gap = _decimal_or_zero(
            scenario_rows["base"]["adjusted_remaining_gap_to_wall_bil"]
        )
        for calibration_id, row in scenario_rows.items():
            current_gap = _decimal_or_zero(row["adjusted_remaining_gap_to_wall_bil"])
            if calibration_id == "base":
                row["treasury_calibration_effect_classification"] = "reference_no_change"
            elif current_gap < base_gap:
                row["treasury_calibration_effect_classification"] = "moves_closer_to_wall"
            elif current_gap > base_gap:
                row["treasury_calibration_effect_classification"] = "moves_further_from_wall"
            else:
                row["treasury_calibration_effect_classification"] = "no_gap_change"
    return rows


def forecast_treasury_recipient_calibration_product_summary_rows(
    *,
    forecast_treasury_recipient_calibration_comparison_rows: Sequence[dict[str, str]],
    forecast_treasury_recipient_calibration_registry_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = (
        "forecast_treasury_recipient_calibration_product_summary_noncanonical"
    )
    calibration_by_id = {
        row["treasury_calibration_id"]: row
        for row in forecast_treasury_recipient_calibration_registry_rows
    }
    rows_by_year_profile_calibration: dict[
        tuple[str, str, str], list[dict[str, str]]
    ] = defaultdict(list)
    for row in forecast_treasury_recipient_calibration_comparison_rows:
        rows_by_year_profile_calibration[
            (
                row["forecast_year"],
                row["channel_conversion_profile_id"],
                row["treasury_calibration_id"],
            )
        ].append(row)
    rows: list[dict[str, str]] = []
    for (forecast_year, profile_id, calibration_id), candidate_rows in sorted(
        rows_by_year_profile_calibration.items()
    ):
        best_row = max(
            candidate_rows,
            key=lambda row: (
                _decimal_or_zero(row["adjusted_forecast_incremental_path_ratio"]),
                -_decimal_or_zero(row["adjusted_remaining_gap_to_wall_bil"]),
                _forecast_reference_priority(row),
            ),
        )
        calibration_row = calibration_by_id[calibration_id]
        rows.append(
            {
                "forecast_treasury_recipient_calibration_product_summary_row_id": (
                    "forecast_treasury_recipient_calibration_product_summary::"
                    f"{forecast_year}::{profile_id}::{calibration_id}"
                ),
                "ratio_object_id": "rw_forecast_wall_ratio_path",
                "forecast_year": forecast_year,
                "channel_conversion_profile_id": profile_id,
                "legacy_mpc_scenario_alias": best_row["legacy_mpc_scenario_alias"],
                "treasury_calibration_id": calibration_id,
                "treasury_calibration_band": calibration_row[
                    "treasury_calibration_band"
                ],
                "linked_forecast_treasury_recipient_calibration_row_id": (
                    calibration_row[
                        "forecast_treasury_recipient_calibration_row_id"
                    ]
                ),
                "best_comparison_row_id": best_row[
                    "forecast_treasury_recipient_calibration_comparison_row_id"
                ],
                "best_forecast_path_ratio_scenario_registry_row_id": best_row[
                    "forecast_path_ratio_scenario_registry_row_id"
                ],
                "best_maturity_scenario": best_row["maturity_scenario"],
                "best_holder_scenario": best_row["holder_scenario"],
                "base_treasury_recipient_current_demand_share": best_row[
                    "base_treasury_recipient_current_demand_share"
                ],
                "effective_treasury_recipient_current_demand_share": best_row[
                    "effective_treasury_recipient_current_demand_share"
                ],
                "treasury_support_multiplier_vs_bridge_reference": best_row[
                    "treasury_support_multiplier_vs_bridge_reference"
                ],
                "adjusted_forecast_incremental_path_ratio": best_row[
                    "adjusted_forecast_incremental_path_ratio"
                ],
                "adjusted_remaining_gap_to_wall_bil": best_row[
                    "adjusted_remaining_gap_to_wall_bil"
                ],
                "wall_case_classification": best_row["wall_case_classification"],
                "dominant_direct_component_id": best_row["dominant_direct_component_id"],
                "dominant_assumption_axis": "treasury_recipient_calibration_id",
                "treasury_calibration_effect_classification": best_row[
                    "treasury_calibration_effect_classification"
                ],
                "blocked_claims": calibration_row["blocked_claims"],
                "allowed_use": (
                    "forecast_treasury_recipient_calibration_product_summary"
                ),
                "blocked_use": "runtime_default;canonical_rw_y",
                "exact_blocker": (
                    "treasury_recipient_calibration_product_is_noncanonical"
                ),
                "claim_boundary": claim_boundary,
                "source_status": best_row["source_status"],
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )
    return rows


