def forecast_bank_margin_sidecar_summary_rows(
    *,
    forecast_scenario_product_summary_rows: Sequence[dict[str, str]],
    forecast_path_ratio_scenario_registry_rows: Sequence[dict[str, str]],
    forecast_path_ratio_decomposition_rows: Sequence[dict[str, str]],
    forecast_path_ratio_interpretation_rows: Sequence[dict[str, str]],
) -> list[dict[str, str]]:
    disabled = _disabled_switches()
    claim_boundary = "forecast_bank_margin_sidecar_summary_noncanonical"
    scenario_registry_by_id = {
        row["forecast_path_ratio_scenario_registry_row_id"]: row
        for row in forecast_path_ratio_scenario_registry_rows
    }
    decomposition_by_bundle_component = {
        (
            row["forecast_path_ratio_scenario_registry_row_id"],
            row["component_id"],
        ): row
        for row in forecast_path_ratio_decomposition_rows
    }
    interpretation_by_bundle_component = {
        (
            row["forecast_path_ratio_scenario_registry_row_id"],
            row["component_id"],
        ): row
        for row in forecast_path_ratio_interpretation_rows
    }
    rows: list[dict[str, str]] = []
    for product_row in forecast_scenario_product_summary_rows:
        registry_row_id = product_row["best_forecast_path_ratio_scenario_registry_row_id"]
        scenario_row = scenario_registry_by_id[registry_row_id]
        treasury_row = decomposition_by_bundle_component[
            (registry_row_id, "domestic_nonbank_interest_support")
        ]
        tdc_row = decomposition_by_bundle_component[
            (registry_row_id, "tdc_deposit_current_demand_support")
        ]
        bank_row = decomposition_by_bundle_component[
            (registry_row_id, "bank_retained_margin_support")
        ]
        bank_interpretation_row = interpretation_by_bundle_component[
            (registry_row_id, "bank_retained_margin_support")
        ]
        bank_support = _decimal_or_zero(bank_row["component_value_bil"])
        treasury_support = _decimal_or_zero(treasury_row["component_value_bil"])
        tdc_support = _decimal_or_zero(tdc_row["component_value_bil"])
        numerator_total = _decimal_or_zero(scenario_row["numerator_total_bil"])
        abs_component_total = (
            abs(bank_support) + abs(treasury_support) + abs(tdc_support)
        )
        bank_share_of_numerator = (
            Decimal("0")
            if numerator_total == 0
            else abs(bank_support) / numerator_total
        )
        bank_share_of_abs_direct_components = (
            Decimal("0")
            if abs_component_total == 0
            else abs(bank_support) / abs_component_total
        )
        bank_share_vs_treasury = (
            Decimal("0")
            if treasury_support == 0
            else abs(bank_support) / abs(treasury_support)
        )
        rows.append(
            {
                "forecast_bank_margin_sidecar_summary_row_id": (
                    "forecast_bank_margin_sidecar_summary::"
                    f"{product_row['forecast_year']}::"
                    f"{product_row['channel_conversion_profile_id']}"
                ),
                "ratio_object_id": "rw_forecast_wall_ratio_path",
                "forecast_year": product_row["forecast_year"],
                "channel_conversion_profile_id": product_row[
                    "channel_conversion_profile_id"
                ],
                "legacy_mpc_scenario_alias": product_row["legacy_mpc_scenario_alias"],
                "linked_forecast_scenario_product_summary_row_id": product_row[
                    "forecast_scenario_product_summary_row_id"
                ],
                "best_forecast_path_ratio_scenario_registry_row_id": registry_row_id,
                "linked_bank_decomposition_row_id": bank_row[
                    "forecast_path_ratio_decomposition_row_id"
                ],
                "linked_treasury_decomposition_row_id": treasury_row[
                    "forecast_path_ratio_decomposition_row_id"
                ],
                "linked_tdc_decomposition_row_id": tdc_row[
                    "forecast_path_ratio_decomposition_row_id"
                ],
                "linked_bank_interpretation_row_id": bank_interpretation_row[
                    "forecast_path_ratio_interpretation_row_id"
                ],
                "best_maturity_scenario": product_row["best_maturity_scenario"],
                "best_holder_scenario": product_row["best_holder_scenario"],
                "bank_retained_margin_direct_demand_share": product_row[
                    "bank_retained_margin_direct_demand_share"
                ],
                "bank_retained_margin_support_bil": bank_row["component_value_bil"],
                "treasury_interest_support_bil": treasury_row["component_value_bil"],
                "tdc_deposit_current_demand_support_bil": tdc_row[
                    "component_value_bil"
                ],
                "numerator_total_bil": scenario_row["numerator_total_bil"],
                "bank_share_of_numerator_total": _format_decimal(
                    bank_share_of_numerator
                ),
                "bank_share_of_abs_direct_components": _format_decimal(
                    bank_share_of_abs_direct_components
                ),
                "bank_share_vs_treasury_support": _format_decimal(
                    bank_share_vs_treasury
                ),
                "bank_component_rank_by_abs_value": bank_row[
                    "component_rank_by_abs_value"
                ],
                "bank_margin_vs_depositor_boundary": bank_interpretation_row[
                    "bank_margin_vs_depositor_boundary"
                ],
                "interpretation_boundary_status": bank_interpretation_row[
                    "interpretation_boundary_status"
                ],
                "bank_sidecar_role_status": _forecast_bank_sidecar_role_status(
                    bank_support=bank_support,
                    bank_share_of_numerator=bank_share_of_numerator,
                    bank_share_of_abs_direct_components=(
                        bank_share_of_abs_direct_components
                    ),
                    bank_share_vs_treasury=bank_share_vs_treasury,
                    bank_rank=int(bank_row["component_rank_by_abs_value"]),
                ),
                "blocked_claims": (
                    "depositor_cashflow_proof;welfare;tax;incidence;"
                    "policy_failure;canonical_rw_y"
                ),
                "allowed_use": "forecast_bank_margin_sidecar_summary",
                "blocked_use": "runtime_default;canonical_rw_y",
                "exact_blocker": "bank_margin_sidecar_is_noncanonical_non_depositor",
                "claim_boundary": claim_boundary,
                "source_status": bank_interpretation_row["source_status"],
                "canonical_ratio_entry": "false",
                **disabled,
            }
        )
    return rows


